insert into institution_policy_items (policy_item_id, category, item_kind, key, label, description, value_type, sort_order) values
  ('attr_support_summary', '支援制度属性', 'attribute', 'support_summary', '支援制度の所見', '公開情報・内部資料から読み取った、この機関の支援制度の特徴 (3行以内)。機関詳細ページの冒頭に出す。', 'text', 1105)
insert into institution_policy_assessments (institution_id, policy_item_id, status, attribute_value, evidence_note, source_type, confirmed_at, evaluator) values
  ('inst_kute', 'attr_support_summary', 'established', '認定制度は内部で確定版の規程・委員会内規・支援細則案までそろっているが、施行日が空欄のままで未施行。公開ページにも認定制度・認定企業一覧はなく、称号は6月24日確定版で「工学院大学発スタートアップ」へ統一され、認定も称号授与も学長（認定委員会の議を経る）に一本化された。
insert into institution_policy_assessments (institution_id, policy_item_id, status, attribute_value, evidence_note, source_type, source_url, confirmed_at, evaluator) values
  ('inst_kute', 'pol_cert_rule', 'drafting', '案: 工学院大学における大学発スタートアップの認定に関する規程', '内部資料01_認定規程_確定版_20260624。第1条で本学の研究成果又は人的資源等を活用した法人を「工学院大学発スタートアップ」として認定すると定める。附則の施行日は空欄で未施行。公開のスタートアップ支援ページにも認定制度の記載はない。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_eligible_scope', 'drafting', '案: 知財型・研究成果型・教職員学生型（退職卒業後3年以内）・学長特認', '01_認定規程_確定版_20260624 第2条各号。1号は本学帰属の知的財産権をもとに起業、2号は本学で達成された研究成果又は習得した技術に基づく起業、3号は教職員・学生等が発起人又は設立時の取締役等（退職・卒業後は3年以内）、4号はその他学長が特に必要と認めたもの。04_審査チェックシートは「起業する予定のもの」も確認対象に含める。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_recognition_decider', 'drafting', '案: 学長が認定・称号授与（大学発スタートアップ認定委員会の議を経る）', '01_認定規程_確定版_20260624 第5条第1項で申請書は学長へ提出、第2項で学長が認定委員会の議を経て認定を決定、第6条で学長が称号記により称号を授与。旧案の「理事長が認定・学長が称号授与」から確定版で学長へ一本化された。03_認定委員会内規Fixver_20260807 第2条で委員会は審議結果を学長へ報告する。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_cert_pre_registration', 'drafting', '案: 設立前申請可。認定予定を通知し、設立後に改めて認定', '01_認定規程_確定版_20260624 第5条第4項で、申請者が法人設立前でも認定委員会の議を経て法人設立後に認定を受けられる旨を通知できると定める。第5項で通知を受けた者は設立後に登記事項証明書、定款その他学長が必要と認める書類を提出し、改めて認定を受ける。2026-05-31時点の「検討事項・条文化未確定」から確定版で条文になった。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_validity_years', 'drafting', '案: 5年・更新可（認定手続を準用して審査）', '01_認定規程_確定版_20260624 第6条第2項で称号は認定の日から5年間有効。第3項で有効期間満了3か月前までに更新申請ができ、第4項で認定の手続を準用して更新の可否を決定、第5項で更新後も5年間有効。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_head_office_registration', 'drafting', '案: 貸与施設を所在地とする商業登記を許可（賃貸借契約前提）', '01_認定規程_確定版_20260624 第13条第1項第2号で、貸与した施設について認定スタートアップの所在地とする商業登記を認めると定める。02_支援細則_20260622 第3条で支援申請書に商業登記の要否を記載させ、第3項で賃貸借契約を締結、第4項で登記又は変更後に登記状況を示す書面の提出を求める。第8条第2項で認定の解除・取消時は登記を変更させる。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_facility_lease', 'drafting', '案: 事務室・研究室として学内施設を貸与（有償・賃貸借契約）', '01_認定規程_確定版_20260624 第13条第1項第1号で事務室又は研究室として大学内の施設を貸与できると定め、02_支援細則_20260622 第3条で希望する建物・部屋、期間、使途、使用者、面積及び借料を支援申請書に記載させ、研究企画課との事前協議と賃貸借契約を求める。公開の産学共同研究センター利用ページは本学専任教員が研究責任者となる前提で、企業単独入居は想定されていない。', 'official', 'https://www.kogakuin.ac.jp/research/corc/use.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_shared_equipment', 'drafting', '案: 研究設備・共用機器の利用許可（借料は個別に定める）', '01_認定規程_確定版_20260624 第13条第1項第3号で本学所有の研究設備・共有機器等の利用を許可できると定める。02_支援細則_20260622 第4条で設備名称、期間と月あたり利用時間、使途、利用者、借料（約款等の他の定めがある場合を除く）を申請させ、必要に応じて契約を締結する。学内の共有機器は工学院大学研究機器管理運営委員会規程が学内外への利用促進を審議事項とするが、認定スタートアップ向けの料金区分は未整備。公開の産学連携メニューにも学外機器利用制度の記載はない。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_name_logo_use', 'drafting', '案: 称号は5年間使用可。名称・標章・ロゴは別規程に従う', '01_認定規程_確定版_20260624 第6条第2項で称号の使用期間を定め、第7項で本学の名称、標章、ロゴ等を使用する場合は本学が別に定める規程その他の定めに従うとする。第6項で保証と誤認される表示を禁じ、第12条第1項第5号で違反を取消事由に接続する。ロゴ使用の個別規程は未確認。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_ip_license', 'drafting', '案: 個別契約で優遇措置を定めうる（独占・減免の明文なし）', '01_認定規程_確定版_20260624 第7条第1項で、認定スタートアップは実施許諾契約その他個別契約により許諾された場合に限り本学帰属の知財を利用でき、優遇措置は本学が必要と認める場合に当該契約で定めるとする。第2項で実施許諾又は権利譲渡等の契約締結を義務づける。独占実施権、対価減免、株式対価の明文はない。公開の知的財産権ページには知的財産ポリシーと職務発明規程があるのみで、スタートアップ向け優遇の記載はない。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/intellectualproperty.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_equity_rule', 'drafting', '案: 株式・新株予約権取得規程を整備予定（原案未着手）', 'AMDの規程整備台帳で「大学発SUへの出資・新株予約権規程」は対象のみ確定でAMD原案なし。4/30打合せ資料でも株式及び新株予約権取得等規程は既存なしで整備対象とされている。01_認定規程_確定版_20260624 にも株式・新株予約権に関する条項はない。［検証エージェントは出典を開けず未照合］', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_gap_fund', 'established', '外部GAPファンド・NEDO NEPの申請支援（学内独自資金なし）', '公開のスタートアップ支援ページに、NEDO NEPやGAPファンドの獲得支援、公募制資金援助プログラムの紹介が記載されている。大学独自のGAPファンドや起業準備資金の制度は公開情報にも内部資料にも見当たらない。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_accelerator', 'established', 'ワークショップ・ピッチ・個別メンタリング、2026年度から育成プログラム', '公開のスタートアップ支援ページで、学内向けワークショップ、KUTE-TOKYOスタートアップビジネスピッチコンテスト、個別メンタリング、2026年度から開始する事業化サポートのプログラムが案内されている。窓口は研究推進部研究企画課。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_coi_sidejob', 'established', '就業規則44条の二重就業届出と利益相反管理規程（認定要件に接続）', '01_認定規程_確定版_20260624 第3条第4号で、本学教職員は学校法人工学院大学就業規則第44条（二重就業の届出）、利益相反マネージメントポリシー及び工学院大学利益相反管理規程その他の関係規則に定める手続・許可が適正になされていることを申請要件とする。03_認定委員会内規 第4条第2項第2号で完了又は完了見込みを審査基準に置き、第3条第6項で役員就任予定の委員を審議から外す。役員兼業の専用規程は整備中。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_support_fee', 'drafting', '案: 相談・紹介は無償、施設・機器は有償、広報は費用負担を求めうる', '02_支援細則_20260622 第5条第2項で相談業務、紹介・仲介は原則無償。第6条第2項で広報支援は費用の全部又は一部の負担を求めることができる。第3条・第4条で施設と設備等は借料を申請書に記載し契約を締結する。公開の支援プログラム（ワークショップ、メンタリング等）は参加無料で案内されている。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_certified_count', 'not_started', '認定実績なし（制度未施行、認定企業一覧の公開もなし）', '01_認定規程_確定版_20260624 の附則は施行日が空欄で未施行のため、認定を受けた法人は存在しない。公開のスタートアップ支援ページにも認定企業の一覧や社数の掲載はない。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_cert_update', 'drafting', '案: 5年、満了3か月前に更新申請、認定手続を準用して審査', '01_認定規程_確定版_20260624 第6条第3項で有効期間満了3か月前までに更新申請ができ、第4項で第5条の認定手続を準用して更新の可否を決定、第5項で更新後の称号も5年間有効とし称号記を授与する。更新時も第2条の定義該当と第3条の要件を再確認する構成。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_title_restriction', 'drafting', '案: 保証誤認表示の禁止と免責、違反は取消事由', '01_認定規程_確定版_20260624 第6条第6項で、称号が本学による製品、サービス、技術、安全性、品質、法令適合性、経営状態又は資金調達力の保証を意味すると誤認される表示を禁じる。第8条で本学は内容・品質を保証せず認定・取消による損害も賠償しないと定め、第12条第1項第5号で第6条第6項・第7項違反を取消事由とする。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_cancellation', 'drafting', '案: 取消7事由・称号記返付・表示削除・認定事実の利用停止', '01_認定規程_確定版_20260624 第11条で代表者からの解除申請と称号の返付、第12条第1項で信用失墜、定義不該当、事業実態の喪失、申請の虚偽、称号使用制限違反、報告書未提出、その他不適当の7事由による取消を定める。第3項で取消日以降は認定を受けていた事実を事業に活用してはならず、ウェブサイト、営業資料、採用資料、プレスリリース等から表示を速やかに削除させる。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_report_change', 'drafting', '案: 年次事業報告と解散等の報告を義務化（変更届は未規定）', '01_認定規程_確定版_20260624 第10条第1項で決算日から3か月以内に事業報告書、計算書類、収支決算書等を学長へ提出させ認定委員会が確認する。第2項・第3項で調査又はヒアリング、第4項で解散、破産、民事再生、会社更生、不正競争防止法違反の有罪確定時の報告を義務づける。代表者・所在地・資本構成の変更届は90_論点別比較メモの論点11で追加提案されているが確定版に条文はない。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_support_request', 'drafting', '案: 支援申請書と認定委員会審査（支援細則で申請事項を規定）', '01_認定規程_確定版_20260624 第13条第1項柱書で、支援を必要とする代表者は支援申請書（別紙様式第5号）を提出し認定委員会の議を経て支援を決定する。02_支援細則_20260622 第2条から第6条で施設、設備等、相談・紹介、広報ごとの記載事項と研究企画課との事前協議を定める。03_認定委員会内規 第4条第3項は、別途基準を定める必要のある支援は当該基準が定まるまで審査を行わないとする。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_facility_registration', 'drafting', '案: 学内施設の貸与と貸与施設での商業登記をセットで規定', '01_認定規程_確定版_20260624 第13条第1項第1号（事務室・研究室としての施設貸与）と第2号（貸与施設を所在地とする商業登記の許可）。02_支援細則_20260622 第3条で希望施設、期間、使途と商業登記の要否、面積・借料を申請させ、賃貸借契約と登記状況の書面提出、認定終了時の登記変更まで定める。学内の場所配分は学校法人工学院大学施設の有効利用に関する規程で理事長が決定する枠組み。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_vc_connection', 'established', '学外専門家・金融機関・公募資金プログラムの紹介', '公開のスタートアップ支援ページで、学外のプロフェッショナルや公募制資金援助プログラムの紹介、特許事務所との連携、SusHi Tech Tokyoへの出展が案内されている。東京都の大学発スタートアップ創出支援事業（事業ステップアップ支援）に2025年11月採択され、2027年3月31日までの期間で支援体制を構築する。認定規程案第13条第1項第5号にも他企業への紹介・仲介がある。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_eir', 'unknown', null, '公開のスタートアップ支援ページにスタートアップ統括の特任教授と個別メンタリングの記載はあるが、客員起業家（EIR）としての招聘・任用制度は確認できない。内部の規程案・細則案・委員会内規にもEIRに関する条項はない。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_ip_equity', 'drafting', '案: 実施許諾対価は個別契約。株式・SO対価の規定なし', '01_認定規程_確定版_20260624 第7条は実施許諾又は権利譲渡等の契約締結を求めるのみで、対価の形態は個別契約に委ねる。株式・新株予約権の取得規程が未整備のため、ライセンス対価として株式やストックオプションを受け取る運用は制度として確定していない。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'pol_fund_investment', 'drafting', '案: 大学ファンド・出資は検討段階、現行規程なし', 'AMDのPhase4ヒアリング設計で大学独自ファンド、既存VCとの共同ファンド、マッチングファンド、学校法人の出資制限を検討項目として整理。現行の規程集にも認定規程案にも出資・ファンド組成の条項はなく、公開情報にも大学VCや指定ファンドの記載はない。［検証エージェントは出典を開けず未照合］', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_regulation_owner', 'drafting', 'ハイブリッド: 大学の規程だが改廃は理事長が決定（案）', '01_認定規程_確定版_20260624 の題名は「工学院大学における大学発スタートアップの認定に関する規程」で大学規程の形。一方、第15条で改廃は学長が教授総会の意見を聴いた後に理事長へ提案し理事長が決定する。02_支援細則_20260622 第1条には「学校法人工学院大学における」の旧表記が残っており、名義の統一は未了。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_review_body', 'drafting', '工学院大学発スタートアップ認定委員会（委員長は総合研究所所長）', '01_認定規程_確定版_20260624 第4条で認定委員会を設置し審査を行う。03_認定委員会内規Fixver_20260807 第3条で、研究担当理事、総合研究所所長、総合研究所運営委員会委員から所長が指名する2名程度、総務・人事部長、財務部長、研究推進部長、学外を含む有識者2名程度で構成し、委員長は総合研究所所長。第5条で過半数の出席と出席委員の過半数で議決。事務は研究推進部研究企画課。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_equity_decider', 'drafting', '案: 理事長決裁を想定（規程未整備で未確定）', '2026-05-25の決裁者比較資料で、株式・新株予約権の取得と処分は法人マターとして理事長決裁を標準とし、ハイブリッド案でも理事長決裁と整理。ただし出資・新株予約権規程そのものが未整備のため、決裁者は確定していない。［検証エージェントは出典を開けず未照合］', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_amendment_decider', 'drafting', '案: 規程は理事長が決定（教授総会の意見聴取後）、細則・内規は学長', '01_認定規程_確定版_20260624 第15条で、規程の改廃は学長が教授総会の意見を聴いた後に理事長へ提案し理事長が決定する。02_支援細則_20260622 第10条で細則の改廃は研究推進部長の発議により学長が定め、03_認定委員会内規 第9条で内規の改廃は総合研究所所長の発議により学長が定める。2026-05-31時点の「理事会議決」という整理は確定版で理事長決定に変わっている。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_post_grad_limit', 'drafting', '3年以内: 退職・卒業等から起業まで3年以内（他職不就業要件は削除）', '01_認定規程_確定版_20260624 第2条第3号の括弧書き。旧案にあった「他職に就かず」の要件は、90_論点別比較メモの論点1で限定的に読まれるとして削除又は緩和が提案され、確定版では記載がない。04_審査チェックシートも同じ3年要件で確認する。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_renewal_rule', 'drafting', '更新可（審査あり）: 満了3か月前に申請、認定手続を準用', '01_認定規程_確定版_20260624 第6条第3項から第5項。更新申請は認定と同じ手続を準用するため、認定委員会の議を経て学長が可否を決定する。ただし02_支援細則_20260622 第7条は更新された期間を支援対象から除いている。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_naming', 'drafting', '大学発スタートアップ: 称号は「工学院大学発スタートアップ」', '01_認定規程_確定版_20260624 第1条・第6条。2026-05時点の案は「工学院大学発ベンチャー」だったが、6月24日確定版で規程名も称号もスタートアップに統一された。ベンチャーとの併記は行っていない。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_support_period', 'drafting', '称号期間と同じ: ただし更新後の期間は支援対象外（細則案）', '02_支援細則_20260622 第7条で、支援を行うことができる期間は称号を授与している期間とし、規程第6条第4項により更新された期間を除くと定める。第8条で認定の解除・取消時は支援を終了し、商業登記を行っていた場合は速やかに変更させる。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_support_contents', 'established', '稼働: WS・メンタリング・資金申請支援／案: 施設・登記・機器・広報', '公開のスタートアップ支援ページに、ワークショップ、ピッチコンテスト、個別メンタリング、2026年度開始の事業化サポート、NEDO NEP・GAPファンド申請支援、学外専門家や公募制資金援助プログラムの紹介が掲載。認定に紐づく支援メニューは01_認定規程_確定版 第13条の施設貸与、商業登記、研究設備・共有機器、経営相談、他企業紹介・仲介、広報の6号で、こちらは規程案段階。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kute', 'attr_source_docs', 'established', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html・https://www.kogakuin.ac.jp/news/2025/120391.html・https:/…', '1本目が公開のスタートアップ支援プログラムの正本、2本目が東京都の大学発スタートアップ創出支援事業（事業ステップアップ支援）採択と支援体制構築を告知したニュース、3本目が知的財産ポリシーと職務発明規程の掲載ページ。認定制度そのものの根拠は内部資料01_認定規程_確定版_20260624、02_支援細則_20260622、03_認定委員会内規Fixver_20260807、04_審査チェックシート_20260717。', 'official', 'https://www.kogakuin.ac.jp/research/collaboration/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_cert_rule', 'established', '愛媛大学発ベンチャー認定制度（規則第91号）', '「国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程」令和2年10月21日規則第91号。附則の最終改正は令和8年7月8日施行。第1条で円滑かつ適正な支援のための認定制度と位置づけ、第5条第1項で認定証（別紙様式第2号）を授与し「愛媛大学発ベンチャー」と称することを認める。全11条＋様式。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_eligible_scope', 'established', '大学知財型・役職員学生知財型・退職卒業者型・研究成果型の4類型', '第2条各号。(1)本学所有の知的財産権を基に設立(2)本学の研究成果等に基づく役職員・学生所有の知財を基に設立(3)在籍時の研究成果等に基づく退職・卒業・修了者所有の知財を基に設立(4)その他本学で達成された研究成果等に基づき、国立大学法人法22条1項5号の業務遂行に寄与するもの。第4条で公序良俗違反や本学への名誉毀損等のおそれがないことも申請条件。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_recognition_decider', 'established', '学長（推進会議の審議を経て機構長が推薦）', '第3条。申請者が認定申請書（別紙様式第1号）を研究・産学連携推進機構長へ提出し、機構長が研究・産学連携推進会議で適否を審議、適当と判断した場合に学長へ推薦、学長が認定を決定、機構長が文書で通知する。第5項で機構長は外部有識者への意見聴取と申請者面接を行える。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_cert_pre_registration', 'not_started', '設立後の申請のみ、登記前の条件付認定なし', '第2条は各号とも「設立したもの」を認定対象とし、第5条の認定証様式にも設立年月日欄がある。登記前申請、認定予定通知、条件付認定の条項は規程本文にない。AMD内部資料「SolvioraX SU設立 業務フローと全体スケジュール案」（2026-08-24）も設立登記後に認定申請と整理。なお固定資産等貸付基準第2条1項4号は「創業準備を含む」事業者への貸付を認めており、設立前の施設利用は別経路。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_validity_years', 'established', '認定日から5年、更新可', '第5条第2項で認定の期間は認定した日から5年とし更新できると定める。第3項で更新は代表者が機構長へ申請し、更新に係る認定の手続は第3条を準用する。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_head_office_registration', 'established', '貸与施設を所在地とする商業登記可、有償', '認定規程第9条第1項第2号が、貸与した施設について当該認定大学発ベンチャーの所在地とする商業登記を認めると明記。起業活動支援プログラムページはE.U. Innovation Commonsのレンタルラボ・オフィスを商業登記可能と記載。施設は有償で、貸付料は固定資産等貸付事務取扱細則第9条の貸付料算定基準による。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_facility_lease', 'established', 'E.U. Innovation Commonsに有償入居、原則2年', '認定規程第9条1項1号で事務室・研究室として学内施設を貸与。E.U. Innovation Commons施設管理規程第5条1項3号は原則設立後5年以内の愛媛大学発ベンチャーを利用対象とし、第7条で原則2年以内・1年を限度に延長可、第9条で推進会議の議を経て機構長が可否を決定。施設利用内規はオープンラボ年1,497,600円（特定利用者520,000円）、コワーキング1席月10,000円（税別）、光熱水料別。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０８編　各施設/第０２章　学内施設/31◎愛媛大学E.U. Innovation Commons施設管理規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_shared_equipment', 'established', '研究設備等の利用許可、負担金は別途設定', '認定規程第9条1項3号で研究設備等の利用許可を支援に明記し、同条3項で支援は本学の関係諸規則等によると定める。E.U. Innovation Commons施設利用内規1.3は、専有型スペース利用者が共同実験室の設備・機器を併せて利用する場合に利用負担金を徴収し、額は研究・産学連携推進機構長が別途定めるとする。公開の設備料金表は確認できず。', 'official', 'https://ccr.ehime-u.ac.jp/startup/wp-content/themes/original/dist/assets/pdf/eu_innovation_commons_guidelines.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_name_logo_use', 'established', '称号使用可、取消後は使用禁止。ロゴ条件は不明', '第5条1項で認定証を授与し「愛媛大学発ベンチャー」と称することを認める。第8条3項で取消後は認定を受けていた事実を事業に使用してはならないと定め、第7条の辞退時も認定証を返付する。大学のロゴマーク・校章の使用条件を定める規程は公開情報で確認できず。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_ip_license', 'established', '対価を株式等で受ける特例のみ、減免規定なし', '知的財産権規程第21条がライセンス等の対価の特例を株式等取扱細則に委任。第18条でライセンス活動は原則として技術移転機関を通して行い、第22条2項で必要経費控除後の収益50%を発明者へ支給する。認定ベンチャー向けの独占実施権、実施料減免、サブライセンス優遇を定める条項は公開規則集に見当たらない。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０２章　知的財産/02◎国立大学法人愛媛大学知的財産権規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_equity_rule', 'established', 'ライセンス対価としての株式・新株予約権取得', '「愛媛大学におけるライセンス等の対価として取得する株式等取扱細則」令和元年8月1日学長裁定、令和6年4月1日改正施行。第2条3号で株式等を株式および新株予約権と定義。第3条で相手方が大学発ベンチャーで対価の現金支払が困難と認める場合に株式等を取得できる。第4条で知的財産委員会が財務状況等を踏まえ取得の可否を審査。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０２章　知的財産/05◎愛媛大学におけるライセンス等の対価として取得する株式等取扱細則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_gap_fund', 'established', 'PSI GAPファンド、STEP1上限500万・STEP2上限6,000万', '起業活動支援プログラムページ。STEP1（ビジネスモデル検証型）は期間1年・上限500万円で2025年度4件採択、STEP2（概念実証型）は期間3年・上限6,000万円。応募条件は愛媛大学の研究者であることと起業意思で、修士・博士課程学生は可、学部生は不可。特許出願費用と登記費用は対象外。特許出願前でも応募可だが技術の裏付けが必要。', 'official', 'https://ccr.ehime-u.ac.jp/startup/program/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_accelerator', 'established', 'メンター制度と伴走支援、申請支援・相談窓口', '起業活動支援プログラムページ。学外専門家によるメンター制度、ビジネスプラン作成支援・メンタリング、資金調達・事業化に関する相談、ピッチイベント・外部プログラムへの参加機会、PSI GAPファンド等の申請支援を挙げる。認定に関する事務窓口は研究・産学連携支援部研究・産学連携課（認定規程第10条）。', 'official', 'https://ccr.ehime-u.ac.jp/startup/program/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_coi_sidejob', 'established', '兼業・利益相反手続の完了が認定申請の条件', '認定規程第4条第4号。本学の教職員が設立したものは、国立大学法人愛媛大学兼業規程および国立大学法人愛媛大学利益相反管理規程その他の関係規則等に定める所要の手続、許可等が適正になされていることを申請の条件とする。兼業許可と利益相反管理は認定と独立ではなく、認定申請の前提条件になっている。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_support_fee', 'established', '認定は無償、施設・設備の利用は有償', '認定手続自体に費用の定めはない。施設は固定資産等貸付事務取扱細則第9条により貸付料算定基準で算定した額に消費税を加えた額で有償、減額は業務遂行に特に有益な場合等に限る。無償貸付は貸付基準第3条で国・地方公共団体、災害、協定等に限定。公式ページも施設貸与とファンド投資は別途審査があり約束するものではないと明記。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０６編　大学運営/第０４章　経理/16◎国立大学法人愛媛大学固定資産等貸付事務取扱細則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_certified_count', 'established', '一覧・社数の公開なし、個別ニュースのみ', '大学発ベンチャーのページに認定企業一覧や累計社数の掲載はない。認定は産学連携推進本部のニュースで個別に公表され、直近は2026年1月7日付の株式会社HBNET（医学系研究科の研究成果に基づく経鼻投与製剤技術）。当該記事にも認定番号、累計数、一覧へのリンクの記載はない。', 'official', 'https://ccr.ehime-u.ac.jp/ccr/university-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_cert_update', 'established', '5年ごとの更新申請、更新審査は認定手続を準用', '第5条第2項で認定期間は5年・更新可。第3項で更新しようとする認定大学発ベンチャーの代表者は機構長に申請しなければならず、更新に係る認定の手続は第3条を準用する。すなわち更新時も推進会議の審議と学長の決定を経て要件が再確認される。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_title_restriction', 'established', '取消後の称号使用禁止あり、保証誤認防止条項なし', '第5条1項で称号使用を認め、第8条3項で取消しを受けた代表者は認定証を返付し、取消日以降は認定を受けていた事実を事業に使用してはならないと定める。第7条の辞退時も認定証を返付。品質保証、投資推奨、経営状態の保証と誤認させない趣旨の条項は規程本文にない。公式ページは施設貸与とファンド投資を保証しない旨のみ記載。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_cancellation', 'established', '取消4事由、認定証返付と表示利用停止まで明記', '第8条第1項の取消事由は(1)第2条の定義から著しく逸脱(2)社会的信用を失墜する行為(3)事業報告書等の未提出または第6条2項の報告があった場合(4)その他本学の不名誉となるおそれ。推進会議の判断を受け機構長が学長へ申出、学長が取消す。第2項で別紙様式第4号により通知、第3項で認定証の返付と取消日以降の使用禁止。第7条に辞退制度。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_report_change', 'established', '年次の事業報告書等を提出、変更届の定めなし', '第6条第1項で代表者は任意様式により、当該認定大学発ベンチャーが定めた決算日から3か月以内に事業報告書と収支決算書を機構長へ提出する。第2項で解散、破産手続、民事再生手続、会社更生手続、不正競争防止法21条の罰金刑確定は代表者または清算人が速やかに報告。代表者・所在地・資本構成の変更届の規定はない。未提出は第8条の取消事由。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_support_request', 'established', '支援は認定と別に個別申請・個別審査', '認定規程第9条3項で支援は本学の関係諸規則等によると定める。施設は固定資産等貸付事務取扱細則第5条の施設借受申請書を固定資産管理責任者へ提出、E.U. Innovation Commonsは施設管理規程第8条で利用開始の原則3か月前までに利用申請書を提出し、第9条で推進会議の議を経て管理責任者が可否を決定する。公式ページも別途審査と明記。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０８編　各施設/第０２章　学内施設/31◎愛媛大学E.U. Innovation Commons施設管理規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_facility_registration', 'established', '学内施設の有償貸与と、貸与施設での商業登記', '認定規程第9条1項1号で事務室・研究室の貸与、2号で貸与施設を所在地とする商業登記を認める。E.U. Innovation Commonsは原則設立後5年以内の認定ベンチャーが対象で、利用期間は原則2年・1年を限度に延長可、レンタルラボ・オフィスは商業登記可能。料金はオープンラボ年1,497,600円（特定利用者520,000円）、コワーキング1席月10,000円（税別）。', 'official', 'https://ccr.ehime-u.ac.jp/startup/program/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_eir', 'not_started', '客員起業家（EIR）制度なし', '起業活動支援プログラムページの支援は学外専門家によるメンター制度、伴走型支援、GAPファンド、専門人材マッチングで、客員起業家や起業家人材の招聘制度の記載はない。認定規程第9条の支援も施設・登記・設備・紹介・広報の限定列挙で該当項目はない。', 'official', 'https://ccr.ehime-u.ac.jp/startup/program/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_cxo_pool', 'established', '経営候補者マッチングを支援メニューに明記', '起業活動支援プログラムページが伴走型支援として「専門人材・経営候補者マッチング」を明記。ただし人材プールの規程、登録者数、紹介手続は公開されていない。AMD内部記録（2026-06観測）では実案件の経営者候補は学外から供給されており、大学経由の紹介実績は確認できていない。既存評価のnot_startedを、公開ページの記載を根拠に更新。', 'official', 'https://ccr.ehime-u.ac.jp/startup/program/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_ip_equity', 'established', 'ライセンス対価として株式・新株予約権を取得可', '株式等取扱細則第1条は知的財産権規程第21条に基づく特例で、大学発ベンチャー育成のため対価を現金に代えて株式等で取得する場合の取扱いを定める。第3条で対価の全額または一部を株式等で取得でき、第5条で研究・産学連携担当理事が取得を決定し契約を締結。第7条で発明者報酬は当該株式等を換金して収入を得た場合に支払う。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０２章　知的財産/05◎愛媛大学におけるライセンス等の対価として取得する株式等取扱細則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'pol_fund_investment', 'not_started', '出資・ファンド組成の規程なし', '認定規程第9条の支援は施設貸与、商業登記、設備利用、他企業紹介、広報の限定列挙で出資を含まない。株式等取扱細則も取得原因をライセンス等の対価に限定し（第3条）、現金出資やファンドへのLP出資の規定はない。公式ページは認定によりファンドからの投資が可能になるとしつつ、審査があり投資を約束するものではないと明記。', 'official', 'https://ccr.ehime-u.ac.jp/ccr/university-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_regulation_owner', 'established', '大学規程（国立大学法人愛媛大学 規則第91号）', '認定規程は国立大学法人愛媛大学の規則（令和2年10月21日規則第91号）として制定されている。学校法人規程や研究機関独自規程ではなく、大学法人の規則体系に置かれる。関連する株式等取扱細則と固定資産等貸付基準は学長裁定、E.U. Innovation Commons施設利用内規は機構長制定と、階層が分かれている。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_review_body', 'established', '愛媛大学研究・産学連携推進機構研究・産学連携推進会議', '第3条2項で機構長が推進会議に付議して認定の適否を審議し、適当と判断した場合に学長へ推薦する。第5項で機構長は審議に際し外部有識者への意見聴取と申請者面接ができる。第10条で認定に関する事務は研究・産学連携支援部研究・産学連携課が処理する。推進会議は施設利用許可の審議も担う。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_equity_decider', 'established', '研究・産学連携担当理事（知的財産委員会が審査）', '株式等取扱細則第4条で知的財産委員会が財務状況その他取得の妥当性を踏まえ可否を審査し、委員長が研究・産学連携担当理事へ報告。第5条で理事が取得の可否を決定して学長へ報告し、取得を決定した場合は契約書を取り交わす。第6条で新株予約権の変更・処分（放棄を含む）も委員会審査と理事の承認による。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０２章　知的財産/05◎愛媛大学におけるライセンス等の対価として取得する株式等取扱細則.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_amendment_decider', 'established', '学長（法人の規則として制定・改廃）', '認定規程は規則第91号として制定され、附則は施行日のみで改廃の決裁条項を持たない。同分野の細則が学長裁定、内規が機構長制定と明示されるのに対し、規則は法人の規則として学長が制定する階層にある。基本規則第12条は役員会が国立大学法人法11条3項の重要事項（重要な規則の制定改廃を含む）を審議すると定める。個別の付議実績は非公開。［検証エージェントは出典を開けず未照合］', 'official', 'https://www.ehime-u.ac.jp/wp-content/uploads/2022/03/%E6%84%9B%E5%AA%9B%E5%A4%A7%E5%AD%A6%E8%A6%8F%E5%89%87%E9%9B%86_%E7%AC%AC%EF%BC%90%EF%BC%91%E7%B7%A8%E3%80%80%E5%9F%BA%E6%9C%AC%E8%A6%8F%E5%89%87_01%E2%97%8E%E5%9B%BD%E7%AB%8B%E5%A4%A7%E5%AD%A6%E6%B3%95%E4%BA%BA%E6%84%9B%E5%AA%9B%E5%A4%A7%E5%AD%A6%E5%9F%BA%E6%9C%AC%E8%A6%8F%E5%89%87.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_post_grad_limit', 'established', '期限なし（在籍時研究成果由来の知財が要件）', '第2条第3号は「本学在籍時における研究成果等に基づいて、本学を退職、卒業又は修了した者が所有する知的財産権を基に設立したもの」と定め、退職・卒業・修了からの年限を置いていない。年限ではなく在籍時の研究成果との関係で対象かどうかを判断する構造。ただし施設支援は設立後5年以内という別の期限がある。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_renewal_rule', 'established', '更新可（審査あり）', '第5条第2項で5年・更新可、第3項で代表者が機構長へ更新を申請し、更新に係る認定の手続は第3条を準用する。したがって更新のたびに推進会議の審議と学長の決定を経る。届出のみの更新ではない。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_naming', 'established', '大学発ベンチャー（称号「愛媛大学発ベンチャー」）', '規程名も第5条1項の称号も「愛媛大学発ベンチャー」で統一されている。スタートアップの語は支援側の名称（スタートアップ創出支援、起業活動支援プログラム）に使われるが、認定の称号には使われない。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_support_period', 'established', '支援ごとに別に定める（認定日から原則5年が上限）', '第9条2項で支援は認定された日から原則5年間を限度とし、認定期間5年・更新可（第5条2項）と別建てになっている。個々の支援期間は第9条3項により関係諸規則等で決まり、E.U. Innovation Commonsは原則2年・1年を限度に延長可（施設管理規程第7条）、固定資産等の貸付は1年以内で研究成果活用事業の場合は5年（貸付事務取扱細則第8条）。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_support_contents', 'established', '施設貸与・商業登記・研究設備利用・企業紹介・広報', '認定規程第9条1項1〜5号が支援を限定列挙する。事務室または研究室としての学内施設貸与、貸与施設を所在地とする商業登記、研究設備等の利用許可、研究イノベーション推進本部等による他企業への紹介・仲介、本学主催イベント・広報誌・ホームページでの広報。加えて起業活動支援プログラムでGAPファンド、メンター制度、経営候補者マッチング、申請支援。', 'official', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_ehime', 'attr_source_docs', 'established', 'https://kiteisv.office.ehime-u.ac.jp/愛媛大学規則集/第０４編　社会連携/第０１章　社会連携/07-2◎国立大学法人愛媛大学における大学発ベンチャーの認定に関する規程.pdf・https://kitei…', '認定制度の本体は認定規程（規則第91号）、株式・新株予約権の取得は株式等取扱細則、施設・資金・伴走の運用は起業活動支援プログラムページが読み口になる。施設の料金と期間はE.U. Innovation Commons施設管理規程および施設利用内規、貸付の一般ルールは固定資産等貸付事務取扱細則と貸付基準で補う。', 'internal_doc', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_cert_rule', 'established', '香川大学発ベンチャー認定規則（令和3年6月1日施行）', '「国立大学法人香川大学における大学発ベンチャーの認定に関する規則」令和3年6月1日制定、令和4年4月1日改正施行。第1条は大学発ベンチャーの円滑かつ適正な支援を目的と定め、第3条で学長がセンター会議の議を経て認定し、香川大学発ベンチャー認定証（別記様式第2号）を交付する。第6条で称号使用を認める。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_eligible_scope', 'established', '知財活用型・教職員・学生・退職卒業3年以内、NPO除く法人', '第2条。革新的事業モデルや新規マーケットの創出を企図する株式会社等の法人格を有するもの（NPO法人を除く）で、①本学または教職員が所有する知的財産権を活用して設立、②教職員（退職後3年以内を含む）が研究成果・技術等を基に設立または設立に深く関与、③学生（卒業・修了後3年以内を含む）が研究成果や修得した知識・技術を基に設立または深く関与、④学長が準ずると認めたもの。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_recognition_decider', 'established', '学長（産学連携・知的財産センター会議の議）', '第3条第2項で、学長が産学連携・知的財産センター会議の議を経て認定の可否を決定し申請者へ通知する。第3条第4項で、センター長は審議に際し外部有識者に意見を求め、または申請者への面接を行うことができる。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_cert_pre_registration', 'not_started', '不可。法人格を有する設立済み企業のみ対象', '第2条は対象を「法人格を有するもの」と定義し、第3条第1項の申請主体も企業等の代表者。設立登記前の申請、認定予定通知、条件付認定に当たる条項は規則本文と別記様式第1号から第4号までに存在しない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_validity_years', 'established', '3年・更新可', '第5条第1項で有効期間は認定の日から起算して3年。第2項で満了の1年前から3か月前までに学長へ更新申請、第3項で更新後の期間は前期間満了日の翌日起算、第4項で更新申請には第3条と第4条を準用する。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_head_office_registration', 'unknown', null, '認定規則に施設利用や登記の条項はない。貸付可能施設の案内は不動産貸付規程に基づく短期貸付を扱い、用途を講義・研修・研究会・入学試験・駐車場・スポーツ行事に限定し営利目的の使用を認めないと明記するが、会社の本店所在地としての登記受入れの可否を判断できる規程は公開情報で確認できない。', 'official', 'https://www.kagawa-u.ac.jp/cooperation-community/facilities/10600/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_facility_lease', 'not_started', '起業用の入居施設なし。貸付は講義室と体育施設の短期利用', '貸付可能施設の案内は「国立大学法人香川大学不動産貸付規程」に基づき、対象を6キャンパスの講義室と体育施設等、用途を講義・研修・研究会・入学試験・駐車場・スポーツ行事に限定列挙し、営利を目的とする使用は認めないと明記。申請は不動産貸付申請書（短期）を使用日の20日前までに提出し、使用料は前納。ベンチャー入居用の貸室制度は公開情報に存在しない。イノベーションデザイン研究所の利用案内にも入居や利用料金の記載はない。', 'official', 'https://www.kagawa-u.ac.jp/cooperation-community/facilities/10600/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_shared_equipment', 'established', '共同研究関係者・受託試験依頼者として利用可、利用料は部局が設定', '「香川大学における研究設備・機器の共用に関する規程」令和6年1月31日施行。第6条の利用者の範囲に、学内外における共同研究・プロジェクト研究等の関係者、受託試験・検査等の依頼者、管理部局の長が必要と認めた者を含む。第5条で受託試験・検査等の利用は別に定める。第10条で利用者は管理部局が別に定める利用料を負担する。認定ベンチャー向けの料金区分はない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001256.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_name_logo_use', 'established', '称号は有効期間中のみ使用可。ロゴは学長の事前許可', '認定規則第6条で、認定大学発ベンチャーは「香川大学発ベンチャー」の称号を有効期間に限り使用できる。ロゴは「香川大学ロゴマーク等使用規程」令和6年10月1日施行が別に定め、第5条で構成員以外の使用者は別紙様式第1号により事前に学長へ申請、第6条で学長が許可し、大学の名誉が傷つけられるおそれがあるとき、特定の政治・宗教・思想等の活動に使用するとき、公序良俗に反するときは許可しない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001282.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_ip_license', 'unknown', null, '香川大学職務発明規程（平成16年4月1日）は権利の帰属、届出、知的財産帰属決定会議による決定、権利譲渡書、発明者への補償を対象とし、実施許諾の条件を定めていない。認定ベンチャーへの独占許諾、対価減免、株式対価の条項は同規程に存在せず、実施許諾を扱う取扱要項の有無は公開情報で確認できない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00000333.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_equity_rule', 'unknown', null, '公開規則集で、大学法人が株式または新株予約権を取得・保有・処分する規程を確認できない。国立大学法人香川大学インサイダー取引防止規程（令和2年10月1日）は教職員等個人の売買手続を対象とし、法人による取得保有の条項を含まない。AMD内部資料2026-05-31_ERS_hearing_checklist.mdは2025年4月施行の取扱規程の存在を記すが、原典未確認かつ実運用例も未確認として次回ヒアリング事項に置かれている。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001038.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_gap_fund', 'unknown', null, '［自動検証で否認: センターページにPSI関連記述なし(2回確認)］元の主張(established): PSIへ共同機関として参画、GAP資金の導線あり。産学連携・知的財産センターのページに「PSI（Peace&Science Innovation）事業への参画」の節があり、JST「大学発新産業創出プログラム（START）スタートアップ・エコシステム形成支援事業」により広島大学を主幹機関とするプラットフォームPSIへ令和5年10月1日より共同機関として参画と明記。PSIは中・四国地域最大規模の大学発ベンチャー支援ファンドと記載。学内独自のGAPファンドや起業準備資金は確認できない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_accelerator', 'established', '起業支援と科学技術相談をセンター業務に明記、窓口あり', '産学連携・知的財産センターの事業・サポート内容に、知的財産に関することとして「特許を利用したベンチャーの起業支援」、産学官交流に関することとして「企業等からの科学技術相談」を掲げ、技術相談は申込フォームで受け付ける。伴走型アクセラレーションプログラムやメンタリングの制度化までは同ページに記載がない。', 'official', 'https://www.kagawa-u.ac.jp/faculty/centers/23894/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_coi_sidejob', 'established', '兼業規則と利益相反諸規則の手続完了を認定基準に明記', '認定規則第4条第4号は、本学の教職員が設立したものについて、国立大学法人香川大学職員兼業規則、利益相反に係る諸規則、その他関係規則等に定める所要の手続、許可等が適正になされていることを認定基準とする。認定審査が兼業許可と利益相反管理に接続する構造。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_support_fee', 'unknown', null, '認定規則第12条は支援を行える範囲と期間だけを定め、有償無償の別を書いていない。共用研究設備・機器は同規程第10条で利用料負担、不動産貸付は使用料前納で有償だが、認定に伴う支援の対価区分を示す文書は公開情報で確認できない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_certified_count', 'established', '現在3社・累計12社、企業名一覧を公開', '「香川大学発ベンチャー」ページで、現在認定している3社と過去に認定した9社を合わせ累計12社を、企業名・設立年月日・主な製品サービスの表で公開している。同ページに、本学は当該ベンチャーに対する法的責任を負わない旨の注記がある。', 'official', 'https://www.kagawa-u.ac.jp/faculty/centers/23894/23923/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_cert_update', 'established', '3年ごとに更新申請、認定手続と基準を準用', '第5条第2項で有効期間満了後も引き続き認定を受けようとするときは満了の1年前から3か月前までに学長へ更新申請。第3項で更新後の有効期間は前期間満了日の翌日起算。第4項で更新申請には第3条の認定手続と第4条の認定基準を準用し、更新時にも要件を再確認する。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_title_restriction', 'established', '品質を保証しない旨の免責条項あり、称号は期間限定', '第11条第1項で、本学は認定大学発ベンチャーの製品、サービス等の内容及び品質を保証しないと明記。第2項で事業から生じた結果または損害についていかなる法的責任も負わない。第6条で称号の使用は有効期間に限る。投資推奨や経営状態の保証を否定する個別条項はないが、品質保証の否定は明文化されている。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_cancellation', 'established', '学長がセンター会議の議を経て取消、反社該当は即時取消', '第9条第1項の取消事由は、定義からの著しい逸脱、社会的信用を失墜する行為、第7条第2項の報告事由や企業活動の実態喪失、その他大学の不名誉となるおそれ。第2項で別記様式第4号により代表者へ通知。第10条は反社会的勢力および反市場的勢力に該当する場合の無催告即時取消と、取消による損害を賠償しない旨。第8条は代表者からの解除申出。称号の返付、表示削除、営業利用停止の条項はない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_report_change', 'established', 'センター長が事業報告書を請求可、解散・破産等は速やかに報告', '第7条第1項で、センター長は代表者に対し指定する年度の事業報告書または本学が指定する事項を記載した報告書を請求できる。第2項で、会社法の解散、破産手続、民事再生手続、会社更生手続、不正競争防止法の罰金刑確定に該当したときは代表者または清算人が速やかに報告する。代表者、所在地、資本構成の変更届に当たる条項はない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_support_request', 'unknown', null, '第12条は包括的な支援条項で、支援申請書や個別審査の定めがない。別記様式は第1号が認定申請、第2号が認定証、第3号が解除申請、第4号が取消通知の4種のみ。第14条は認定に関し必要な事項を別に定めるとするが、この雑則の有無と内容は公開情報で確認できない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_facility_registration', 'not_started', '起業用施設の入居制度と学内本店登記の定めなし', '認定規則に施設利用と登記の条項はない。貸付可能施設の案内は不動産貸付規程に基づき対象を講義室と体育施設等に限定列挙し、用途も講義・研修・入学試験・駐車場・スポーツ行事に限り営利目的の使用を認めない。インキュベーション施設の公開情報はなく、イノベーションデザイン研究所の利用案内にも入居可否と料金の記載がない。登記受入れの明文も存在しない。', 'official', 'https://www.kagawa-u.ac.jp/cooperation-community/facilities/10600/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_vc_connection', 'unknown', null, '［自動検証で否認: センターページにPSI関連記述なし(2回確認)］元の主張(established): PSI経由でスタートアップ支援機関・自治体へ接続。産学連携・知的財産センターのページに、PSIには共同機関として中・四国の国公私立大学が、協力機関としてスタートアップ支援機関や自治体等が参画すると明記され、人材・知・資金が循環するエコシステムの形成を目標に掲げる。センターの事業内容にも四国TLOや関連機関と連携・協力した新規事業分野の開拓がある。個別のVCや金融機関への紹介制度は確認できない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_eir', 'unknown', null, '客員起業家、起業家メンター、起業家人材の招聘に当たる制度は、認定規則にも産学連携・知的財産センターの公開ページにも記載がない。AMD内部資料2026-05-31_ERS_hearing_checklist.mdでも次回ヒアリングの確認事項として未確認扱い。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_cxo_pool', 'unknown', null, '大学発ベンチャーへ経営人材（CEO・CXO候補）を紹介、マッチングする制度は、認定規則にも産学連携・知的財産センターの公開ページにも記載がない。AMD内部資料2026-05-31_ERS_hearing_checklist.mdでも次回ヒアリングの確認事項として未確認扱い。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_ip_equity', 'unknown', null, '香川大学職務発明規程は権利の帰属と発明者補償を対象とし、実施許諾の対価に関する定めがない。ライセンス対価として株式や新株予約権を受け取る規程は公開情報で確認できない。AMD内部資料2026-05-31_ERS_hearing_checklist.mdは関連する取扱規程の存在に触れるが原典未確認で、IPライセンス対価としての運用有無を次回ヒアリング事項としている。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00000333.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'pol_fund_investment', 'unknown', null, '大学VC、認定VC、LP出資、指定ファンド、大学出資会社経由の投資に関する規程は公開規則集で確認できない。PSIへの参画は広島大学が主幹機関のプラットフォームへの共同機関としての参加であり、大学自身の出資やファンド組成を示す記載はない。', 'official', 'https://www.kagawa-u.ac.jp/faculty/centers/23894/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_regulation_owner', 'established', '大学規程（国立大学法人香川大学の規則）', '規程名は「国立大学法人香川大学における大学発ベンチャーの認定に関する規則」で、法人本体が定める規則。第13条で認定事務は産学連携・知的財産センターと地域創生推進部地域連携推進課が連携して処理する。学校法人規程やセンター内規ではない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_review_body', 'established', '産学連携・知的財産センター会議', '第3条第2項で認定の可否は産学連携・知的財産センター会議の議を経て決定し、第9条第1項の取消も同会議の議を経る。第3条第4項でセンター長は外部有識者への意見聴取または申請者面接を行える。事務は第13条によりセンターと地域創生推進部地域連携推進課が担当する。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_equity_decider', 'unknown', null, '株式・新株予約権の取得や処分を決裁する主体を定めた規程を公開情報で確認できない。認定規則には株式に関する条項がなく、インサイダー取引防止規程も教職員個人の売買を対象とする。次回ヒアリングでの確認事項。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_amendment_decider', 'established', '学長（事前に産学連携・知的財産センターの意見）', '認定規則第15条で、この規則および雑則を制定改廃する場合は事前にセンターの意見を徴する。諸規則等の制定等に関する事務処理細則第3条と第4条は諸規則等を学長制定と部局長等制定に区分し、学長制定分は所管課が原案を作成して企画総務部総務課へ依頼し、必要に応じ基準規則第6条の付議機関の審議を経ると定める。最終付議機関の区分までは公開情報で特定できない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00000067.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_post_grad_limit', 'established', '3年以内（退職・卒業・修了から企業設立まで）', '第2条第2号で、本学を退職した者は退職日から企業設立日までの期間が3年以内なら教職員に含む。第3号で、卒業または修了した者は卒業等の日から企業設立日までが3年以内なら学生に含む。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_renewal_rule', 'established', '更新可（審査あり）。満了1年前から3か月前に申請', '第5条第2項で更新申請の期間を定め、第4項で更新申請に第3条の認定手続と第4条の認定基準を準用する。したがって更新は届出ではなく、センター会議の議を経る審査を伴う。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_naming', 'established', '大学発ベンチャー（称号は「香川大学発ベンチャー」）', '規則名も定義も「大学発ベンチャー」を用い、第6条で認定を受けた企業が「香川大学発ベンチャー」の称号を有効期間に限り使用できると定める。スタートアップの語や独自名称は使っていない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_support_period', 'established', '称号期間と同じ（支援は認定後3年間を限度）', '第12条第2項で支援を行う期間は原則として認定後3年間を限度とする。第5条第1項の認定有効期間も3年で、称号の使用期間と支援期間が一致する設計。支援ごとに別期間を定める条項はない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_support_contents', 'unknown', null, '第12条第1項は「本学における関係規則等に基づき、本学の管理運営及び教育研究に支障のない範囲において、支援を行うことができる」との包括条項で、施設、登記、機器、知財、広報、相談、紹介、資金といったメニューを列挙していない。香川大学発ベンチャーのページにも認定後の支援メニューの記載がない。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_kagawa', 'attr_source_docs', 'established', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html・https://www.kagawa-u.ac.jp/faculty/centers/2389…', '1本目は認定規則の現行条文（規則集の本文ページ。既存データのPDFと同内容で、改正沿革まで確認できる）。2本目は認定企業一覧と社数。3本目は産学連携・知的財産センターの事業内容とPSI参画。施設は貸付可能施設の案内、機器は研究設備・機器の共用に関する規程が補助資料。', 'official', 'https://www.kagawa-u.ac.jp/somu/kisoku/reiki_honbun/x872RG00001059.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_cert_rule', 'established', 'NIMSベンチャー援助等規程による名称使用許可制度', 'NIMSベンチャー援助等規程（平成15年1月23日 15規程第2号、直近改正2026規程第32号・令和8年4月1日施行）第3条・第4条。理事長が「NIMS発ベンチャー」「NIMS成果活用ベンチャー」の名称使用を許可し、様式2の許可書を交付、第4条第4項で機構内外に周知・公表する。第6条の援助対象決定を受けたときは名称使用許可を得たものとみなす二段構え。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_eligible_scope', 'established', '特許等成果を活用する成果活用事業者。職員起業か否かで2区分', '第2条第3号から第5号で、機構の特許等成果を活用した事業を主たる事業とする成果活用事業者をNIMSベンチャーとし、うち職員が起業したものをNIMS発ベンチャー、それ以外をNIMS成果活用ベンチャーと区分。第5条第2項に適格性9要件があり、既存企業では実現が困難な技術の実用化、職員等の役員就任や株式保有による主体的関与、現職職員の兼業等またはクロスアポイントメント出向、参画しない共同発明者の了解、収益性と成長の蓋然性を求める。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_recognition_decider', 'established', '理事長（NIMSベンチャー等審査委員会の審査、理事会議で決定）', '第4条第2項で名称使用の許可者は理事長。援助対象は第6条で、理事長が第7条のNIMSベンチャー等審査委員会に審査を付託し、その結果を踏まえ理事会議で適格性の該否を決定し、様式4の援助対象通知書を交付する。第19条により、名称使用許可と援助対象決定に関する事務は外部連携部門スタートアップ支援室が行う。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_cert_pre_registration', 'established', '設立前でも申請可。登記簿写は設立後に提出', '第4条第1項が申請者を「成果活用事業者又はこれを起業しようとする者（成果活用事業者等）」と定義し、設立登記前の申請を明文で認める。様式1と様式3はいずれも設立又は定款変更の予定年月日を記入させ、計画中は定款案を提出、登記簿写は設立又は変更後に提出すると注記している。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_validity_years', 'established', '援助対象期間5年以内、3年以内延長可。名称使用に期限なし', '第8条第1項で援助対象期間は5年を超えない期間、理事長が特に必要と認めるときは3年を超えない範囲で延長可。延長の審査と決定の手続は第6条を準用する。名称使用許可自体には有効期間の定めがなく、第3条第3項と第12条第1項各号の取消事由に該当した場合に取り消される。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_head_office_registration', 'not_started', '本店登記の定めなし。名刺等への機構内住所表記のみ', '別記1（7）は、機構内に連絡事務所等を設置した場合に名刺等へ機構内の住所を表記できると定めるにとどまる。援助措置は別記1（1）から（10）の限定列挙で、商業登記の受け入れに関する条項はない。様式1と様式3は本社所在地を申請者側の記載事項として扱っている。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_facility_lease', 'established', '研究開発・連絡事務用スペースを有償貸与、利用料75%減額', '別記1（4）で、固定資産等管理細則第5条に基づき共同研究の範囲外でも研究開発又は連絡事務のためのスペース等の有償利用を認め、年間減価償却費と床面積から算出した月額または日額を75%減額する。光熱水料等は地区ごとの単価で実費徴収、維持費等の間接経費は免除。別記1（3）で共同研究時は施設設備の無償利用。第15条により援助対象外のNIMSベンチャーにも貸与できるが、利用料の減額は準用しない。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_shared_equipment', 'established', '研究設備等を有償利用可、利用料75%減額。共用規程分は対象外', '別記1（5）で、共同研究の範囲外でも固定資産等管理細則第5条に基づき研究設備等の利用を認め、減価償却費から算出した利用料を75%減額、光熱水料等は実費、間接経費は免除。ただし専ら収益事業に該当する場合、当該ベンチャー業務に従事する機構職員が物品管理者等となる場合、施設及び設備の外部への共用に関する規程第2条第1項の共用に該当する場合は除外され、共用設備の利用は外部利用として扱われる。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_name_logo_use', 'established', '称号は理事長の許可制で使用可。ロゴ使用の定めなし', '第3条第1項で、許可を得た成果活用事業者は呼称として「NIMS発ベンチャー」又は「NIMS成果活用ベンチャー」を使用できる。様式2の許可書で使用を許可する名称の区分を特定する。機構のロゴや標章の使用条件に関する条項は本規程にない。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_ip_license', 'established', '契約一時金免除、独占的通常実施権、新発明の優先開示', '別記1（1）で、特許等の実施許諾等に当たり契約一時金の免除、独占的通常実施権又は再実施権付実施の許諾、実施許諾した特許権等に関連する新たな発明等を出願したときの優先的開示を、全部又は一部行うことができる。実施許諾の対価は、成果活用事業者から対価として取得する株式等取扱規程第3条第1号により株式又は新株予約権で収納できる。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_equity_rule', 'established', '出資業務実施規程と株式等取扱規程の2本立て', '別記1（2）で出資業務実施規程に基づく出資を援助措置とする。出資業務実施規程第3条は援助対象NIMSベンチャーへの出資を認め、第5条で総株主の議決権の過半数を取得または保有しないことを原則とする。株式等取扱規程はライセンス供与・施設設備の貸与・共同研究等の対価を株式や新株予約権で収納する取扱いを定め、第8条で株式等に基づく経営参加権は原則行使しないとする。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sry.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_gap_fund', 'not_started', '資金助成なし。資金支援は機構の出資のみ', '援助措置は別記1（1）から（10）の限定列挙で、GAP資金・POC資金・起業準備資金にあたる助成の項目はない。資金供給は出資業務実施規程に基づく出資に限られ、同規程第4条で出資財産は自己収入を原資とする金銭または有形固定資産とされる。NIMSが研究推進法人を務めたSIP第3期「マテリアル事業化イノベーション・育成エコシステムの構築」は2026年3月末で終了しており、公式ポータル「マテスタ」の補助金情報も外部制度の紹介にとどまる。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_accelerator', 'established', '専門家相談は無料、連携構築助言。支援室が窓口', '別記1（8）で、機構が顧問契約等を締結している法務・知的財産等の専門家への相談機会を提供し、相談料は無料（上場後は実費相当額を徴収）。別記1（10）で第三者との連携構築に関する助言その他の援助。第19条により事務は外部連携部門スタートアップ支援室が担い、同室は組織ページでもスタートアップとその創業の支援を行う部署と明記される。期別の公募型アクセラレーションプログラムとしての定めはない。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_support_fee', 'established', '認定と専門家相談は無償。施設・設備は有償で75%減額', '名称使用許可と援助対象決定について手数料の定めはない。別記1（8）②で専門家への相談料は無料、ただし上場した場合は実費相当額を徴収。別記1（4）（5）で施設等と研究設備等は有償利用とし利用料を75%減額、光熱水料等は実費徴収、間接経費は免除。別記1（6）で援助に伴う事務的経費も免除。特許等の実施許諾は契約一時金を免除する。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_certified_count', 'established', '18社を一覧公開（NIMS発17社・成果活用1社）', '公式ページ「NIMSベンチャー企業情報」（2025年4月28日更新）に、NIMS発ベンチャー17社とNIMS成果活用ベンチャー1社を、NIMSベンチャー通し番号・会社名・事業内容・設立日つきで掲載。通し番号は第24号まで進んでおり、事業を終了したベンチャー企業は記載しないと注記されている。', 'official', 'https://www.nims.go.jp/business/venture-lab.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_cert_update', 'established', '更新申請あり。援助対象は5年、3年以内延長可', '様式3は「NIMSベンチャー援助措置対象申請書（新規・更新）」で、既援助対象期間を記入させ、延長申請では当該期間の事業報告書に各事業年度の収支決算を記載して添付させる。第8条第2項で延長の審査と援助対象決定の手続は第6条を準用し、NIMSベンチャー等審査委員会の審査と理事会議の決定を経る。名称使用許可自体には有効期間と更新手続の定めがない。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_title_restriction', 'established', '保証と誤認させる行為を禁止。故意の誤認は取消事由', '第3条第2項で、名称を称したことや援助措置を受けたことによって生じた損失・損害について機構は責任を負わない。様式2と様式4の留意事項は、名称使用許可が事業会社としての優良さ・信頼性・将来性を保証するものではなく、関係会社等としての特別な関係の発生も意味しないと明記し、保証と誤認させる行為を厳禁する。第12条第1項第6号で故意の誤認惹起行為を援助対象の取消事由とする。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_cancellation', 'established', '取消事由9項目と協議取消4項目。取消書を交付', '第12条第1項に、社会的背信行為、覚書等の重大な違反、機構業務への支障、企業活動の停止や事実上の倒産、第三者の支配下に入ったとき、保証と誤認させる行為、安全保障貿易輸出管理等の法令遵守を怠ったとき、特許等成果の活用をやめたときなど9事由。第2項に本人希望、株式の店頭公開・上場、主たる事業でなくなったときなど協議による取消4事由。第13条で必要に応じ覚書を解約し、様式5の取消書を交付する。称号の返付や表示削除の手続は定めていない。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_report_change', 'established', '毎事業年度の事業報告書と翌年度以降の事業計画書を提出', '第11条第1項で、援助措置を受けるNIMSベンチャーは援助期間中、毎事業年度の事業報告書と翌年度以降の事業計画書を提出する。第2項で企業活動の状況に関する報告徴求と調査。第3項で援助措置を受けないNIMSベンチャーにも毎事業年度の事業報告書を求める。代表者・所在地・資本構成の変更届や解散時報告の様式は定めていない。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_support_request', 'established', '様式3で希望する援助措置を個別申請、協議のうえ実施', '様式3の「その他希望する援助措置」欄で、研究設備の貸与を物品管理番号・設備名・物品管理者単位、施設の貸与を地区・建物・貸与対象面積・用途単位でチェックして申請する。第9条第1項で援助対象決定後、事業と法人の成長の蓋然性や収益性を踏まえて協議のうえ援助措置の全部又は一部を行う。第10条で援助措置の種類と内容、遵守事項を確認する覚書を締結する。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_facility_registration', 'established', '施設・設備の有償利用は可。本店登記の定めなし', '別記1（4）（5）で施設等と研究設備等の有償利用および利用料の75%減額、第15条で機構の業務に支障を及ぼさない範囲での施設又は設備の貸与、第16条で施設等の貸与を受け賃貸借契約を締結したベンチャー従業員に「NIMSベンチャー従事者」の身分を付与すると定める。一方、機構内の住所利用は別記1（7）の名刺等への表記に限られ、商業登記の受け入れを定めた条項はない。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_vc_connection', 'established', 'VC等の紹介と第三者との連携構築援助を措置化', '別記1（9）で、機構が得た情報のうちベンチャー企業活動の促進に資するものを提供し、機構と関係を持つベンチャーキャピタル等を紹介することを含むと明記。別記1（10）で第三者との連携構築に関する助言その他の援助。いずれも援助対象期間終了後のNIMS発ベンチャーへの継続的援助措置の対象にも含まれる。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_eir', 'not_started', 'EIR制度なし。支援室が制度化の検討意向を表明', '援助措置は別記1の限定列挙で、客員起業家の招聘や起業家人材の受入れにあたる項目はない。援助等規程第16条の従業員等の受入れも、兼業等やクロスアポイントメントで機構の身分を兼ねる者と、施設設備の貸与を受けた従業員に限られる。スタートアップ支援室の担当者は2025年8月公開の取材記事で、現時点でEIR制度はないが機構に合った仕組みとして検討したいと述べている。', 'official', 'https://startupclass.co.jp/article/2025/08/25/nims/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_cxo_pool', 'not_started', '経営人材プールなし。外部支援機関への橋渡しで対応', '援助措置の限定列挙にCEO・CXO候補の紹介やマッチングの項目はなく、人材面の支援は別記1（10）の第三者との連携構築援助に含まれうるにとどまる。スタートアップ支援室の担当者は2025年8月公開の取材記事で、研究者からの起業相談で最も多いのは一緒に取り組む仲間が見つからないことであり、外部のインキュベーターや地域の研究支援センターにつないでチーム作りを支援していると述べている。', 'official', 'https://startupclass.co.jp/article/2025/08/25/nims/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_ip_equity', 'established', 'ライセンス供与の対価を株式・新株予約権で収納可', '成果活用事業者から対価として取得する株式等取扱規程（令和4年4月26日 2022規程第25号）第3条第1号で知的財産権に係るライセンス供与の対価、第2号でNIMSベンチャーからの施設又は設備の貸与に係る対価、第3号で共同研究又は業務実施の対価を株式等で収納できる。第4条で現金支払いが資金繰りや経営に重大な影響を及ぼす場合等を条件とし、第5条で取得はNIMSベンチャー等審査委員会の審査を踏まえ理事会議が決定する。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005srt.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'pol_fund_investment', 'established', '機構が援助対象ベンチャーへ直接出資。ファンド組成はなし', '出資業務実施規程（令和2年3月10日 2020規程第15号）第3条で援助対象NIMSベンチャーへの出資を認め、第4条で出資財産は自己収入を原資とする金銭または有形固定資産、第5条で議決権の過半数を取得・保有しないことを原則とする。第6条で外部専門機関への委託等による事前適性調査、出資業務審査委員会の審査、理事会議の決定という手続を定める。大学VC、LP出資、指定ファンドに相当する規程は規程一覧に見当たらない。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sry.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_regulation_owner', 'established', '研究機関規程（物質・材料研究機構の機構規程）', '認定の根拠はNIMSベンチャー援助等規程（平成15年1月23日 15規程第2号、直近改正2026規程第32号・令和8年4月1日施行）で、国立研究開発法人物質・材料研究機構が理事長名で制定する機構規程。関連する出資業務実施規程、成果活用事業者から対価として取得する株式等取扱規程、兼業等規程も同じ規程体系に置かれ、情報公開ページの規程一覧で公開されている。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_review_body', 'established', 'NIMSベンチャー等審査委員会（決定は理事会議）', '第7条で機構にNIMSベンチャー等審査委員会を置き、理事長の委嘱を受けて援助対象申請等の審査と重要事項の審議を行うと定める。運営は別に定める。第6条第2項・第3項で理事長が同委員会に審査を付託し、その結果を踏まえ理事会議が援助対象適格性を決定する。事務局は外部連携部門スタートアップ支援室（第19条）。出資については出資業務実施規程第7条の出資業務審査委員会が別に審査する。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_equity_decider', 'established', '理事会議（審査委員会の審査を踏まえて決定）', '株式等取扱規程第5条で、対価としての株式等の取得はNIMSベンチャー等審査委員会の審査を踏まえ理事会議が決定し、第10条で売却の決定も同様。新株予約権の権利変更や処分は同規程第6条第4項で委員会の議を経る。出資は出資業務実施規程第6条第5項で理事会議が可否と出資条件を決定し、第12条の重要な議決権行使、第13条の株式等の処分も理事会議が決定する。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005srt.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_amendment_decider', 'established', '理事長（立案は所管室長、手続は法務・コンプライアンス室）', '制文規程（平成13年4月2日 13規程第1号）第2条で、規程等は同規程の手続により理事長が制定したものと定義する。第4条で制定および改廃の立案責任者は当該業務を所管する室長で、原案を法務・コンプライアンス室長に提出し、同室長が所要の調整を行ったうえで制定又は改廃の手続をとる。第13条で主管室は法務・コンプライアンス室。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005s67.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_post_grad_limit', 'not_started', '規定なし。現職職員の関与を適格性要件とする', '第2条第1号は特許等成果を「職員等（キャリア形成職員、任期制職員及び退職者を含む。）が在職中になした研究開発の成果」と定義するが、退職後何年以内という期限は置かない。第5条第2項第6号・第7号は、職員等の役員就任や株式保有による主体的関与と、現職職員の兼業等またはクロスアポイントメント出向によりノウハウを活用できる体制を適格性要件とし、年数ではなく現在の関与で判断する構成になっている。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_renewal_rule', 'established', '更新可（審査あり）。延長は3年以内、様式3で申請', '様式3が新規・更新兼用で、延長申請の場合は既援助対象期間の事業報告書（各事業年度の収支決算を記載）の添付を求める。第8条第1項で理事長が特に必要と認めるときは3年を超えない範囲で援助対象期間を延長でき、第2項で審査および援助対象決定の手続は第6条を準用し、NIMSベンチャー等審査委員会の審査と理事会議の決定を経る。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_naming', 'established', '独自名称：NIMS発ベンチャー／NIMS成果活用ベンチャー', '第2条第4号・第5号と第3条第1項。機構の職員が起業したものを「NIMS発ベンチャー」、それ以外を「NIMS成果活用ベンチャー」と呼称し、様式1と様式2でどちらの区分かをチェックして申請・許可する。公式ページ「NIMSベンチャー企業情報」も同じ2区分で一覧を掲載しており、大学発ベンチャー・大学発スタートアップという語は用いない。', 'official', 'https://www.nims.go.jp/business/venture-lab.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_support_period', 'established', '個別契約（覚書）。名称使用は無期限、援助は5年以内', '第10条で、援助対象決定後に事業内容、遵守すべき事項、援助措置の種類と内容を確認する覚書を締結し、継続的援助措置を行うときも別に覚書を締結する。援助対象期間は第8条で5年以内（3年以内の延長可）。名称使用許可には期間の定めがない。第9条第2項の継続的援助措置はNIMS発ベンチャーのみが対象で、別記2の注記によりNIMS成果活用ベンチャーは対象外。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_support_contents', 'established', '特許実施許諾・出資・施設貸与・設備利用・専門家相談・VC紹介等', '別記1に10項目を限定列挙。（1）特許等の実施許諾等（契約一時金免除、独占的通常実施権、新発明の優先開示）（2）出資（3）共同研究における施設設備の無償利用（4）施設等の有償利用と利用料75%減額（5）研究設備等の有償利用と利用料75%減額（6）援助に係る事務的経費の免除（7）機構内の住所表記使用の許可（8）専門家への相談機会の提供（無料）（9）情報の提供（VC等の紹介を含む）（10）第三者との連携構築援助。別記2で、援助対象期間終了後のNIMS発ベンチャーには（2）（4）（5）（6）（7）（9）（10）を利用料減額を除いて継続する。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_nims', 'attr_source_docs', 'established', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz-att/qqllln0000005sro.pdf・https://www.nims.go.jp/nims/disclosure…', '制度本体はNIMSベンチャー援助等規程のPDF。資金と株式の扱いは出資業務実施規程、および同じ規程一覧にある成果活用事業者から対価として取得する株式等取扱規程。認定の区分と実績一覧は公式ページ「NIMSベンチャー企業情報」。規程集の入口は情報公開ページの規程一覧で、兼業等規程や制文規程も同じページから取得できる。', 'official', 'https://www.nims.go.jp/nims/disclosure/qqllln0000005rhz.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_cert_update', 'not_started', '有効期間・更新審査の定めなし（掲載は継続）', '大学発ベンチャーは規程による認定ではなく、産学公連携・研究推進センター「大学発ベンチャー」ページでの登録・掲載運用。同ページに認定期間、更新可否、更新審査、要件再確認の記載はない。掲載一覧には2002年設立の企業から2025年設立の企業までが並び続けており、期間で入れ替える運用の痕跡もない。山口大学規則集（学内規程データベース）の全編を通覧しても認定規程は存在しない。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_title_restriction', 'established', '大学は法的責任を負わない旨の免責記載のみ', '「大学発ベンチャー」ページの一覧末尾に「留意事項：本学は，これらのベンチャー企業に対する法的責任を負うものではありません。」と明記。品質保証・投資推奨・経営状態保証と誤認させない趣旨の記載はこの一文にとどまる。称号の使用範囲、広告等での表示方法、使用停止を定めた条項は同ページにも規則集にも見当たらない。なお大学名義の共催・後援等については別途「国立大学法人山口大学等名義の使用承認に関する要項」があり、承認基準・承認条件・承認の取消しを定めるが、対象は催事の名義使用でベンチャーの称号ではない。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_cancellation', 'not_started', '取消事由の定めなし（削除は本人申出で受付）', '「大学発ベンチャー」ページの問い合わせ欄に「「山口大学発ベンチャー」に関して，登録・削除・修正等のご要望がありましたら，学術研究部産学連携課産学連携係までご連絡ください」とあるのみで、削除は申出ベースの運用。大学側からの取消事由、称号返付、表示削除義務、営業利用停止を定めた条項は同ページにも山口大学規則集にもない。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_report_change', 'not_started', '年次報告・変更届の定めなし（任意の申出のみ）', '「大学発ベンチャー」ページが受け付けるのは「登録・削除・修正等のご要望」に限られ、事業報告・決算の年次提出、代表者・所在地・資本構成の変更届、解散時報告を義務づける記載はない。掲載企業に継続的な報告義務を課す規程も山口大学規則集に存在しない。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_support_request', 'established', '施設は機構長の利用許可制、起業相談は事前提出の予約制', 'レンタルスペースのページで、新事業創出支援スペースの利用資格を「本法人の役職員」「本学の学生」「機構長が利用を許可した学外者」「その他機構長が適当と認めた者」と定め、利用期間は原則3年以内、更新の際は審査が必要としている。ベンチャー起業支援室のページでは、起業相談は「起業相談ヒアリングシート」の事前提出による予約制と明記し、学外者用のWord様式も配布。掲載（称号）とは別に、支援ごとの個別申請・許可の導線がある。', 'official', 'https://web.archive.org/web/20260216031356/http://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=43', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_facility_registration', 'established', '新事業創出支援スペース入居で登記可、研究室登記は不可', 'ベンチャー起業支援室ページのよくある質問で「産学公連携･研究推進センターのレンタルスペースに空室がある場合は，新事業創出支援スペースとして貸し出しをしています。また，会社の登記所在地とすることも可能です」「研究室を起業する会社の登記所在地とすることはできますか？→できません」と回答。同スペースは大学研究推進機構の常盤地区にあり、使用料1,500円/㎡月＋光熱水費実費、利用期間は原則3年以内。ページ現在の表示では空室なし。', 'official', 'https://web.archive.org/web/20251218185608/https://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=3949', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_vc_connection', 'established', '山口フィナンシャルグループと共同取組、地域金融連携あり', '2020年1月27日発表の共同取組で、山口フィナンシャルグループが山口大学の現役学生・教職員・卒業生を主な投資対象とする投資ファンド「Fun Fun Drive 投資事業有限責任組合」を設立し、大学発ベンチャーを始めとする地域スタートアップへのリスクマネー供給を促進、大学は本取組の支援・運営を連携して行うとしている。ベンチャー起業支援室の活動内容にも「山口フィナンシャル・グループ専門家及び山口ティー・エル・オーとの協働による起業支援」と明記。VCそのものへの紹介制度としての規程は確認できない。', 'official', 'https://web.archive.org/web/2021/http://www.yamaguchi-u.ac.jp/weeklynews/_7735/_8295.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_eir', 'not_started', '客員起業家制度なし（相談・知財・情報提供に限定）', 'ベンチャー起業支援室の活動内容は「山口フィナンシャル・グループ専門家及び山口ティー・エル・オーとの協働による起業支援」「「志」イノベーション道場をハブとしたイベント開催」「起業のための知財相談」「起業に関する各種情報の発信」の4項目に限定列挙。よくある質問の支援内容も相談・知財相談・国の競争的資金活用支援・情報提供に限られ、客員起業家（EIR）や起業家メンターの招聘制度は含まれない。規則集にも該当規程はない。', 'official', 'https://web.archive.org/web/20251218185608/https://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=3949', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_cxo_pool', 'not_started', '経営人材の紹介制度なし（交流の場の提供のみ）', 'ベンチャー起業支援室の活動内容と支援メニューの限定列挙に経営人材の紹介・マッチングは含まれない。「志」イノベーション道場は「学生と優れた起業家・支援者・産業人との接点・ネットワークを提供」する場と説明され、機能はオープンラウンジ、デザインスペース、ホワイトボード、ミーティングルーム、セミナースペースの5つ。CEO/CXO候補を大学発ベンチャーへ紹介する仕組みではない。よくある質問はCEO就任を教職員本人の兼業・利益相反の問題として扱っている。', 'official', 'https://web.archive.org/web/20251110191605/https://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=5544', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_ip_equity', 'not_started', '知財対価としての株式・新株予約権の規程なし', '国立大学法人山口大学知的財産ポリシー現行本文で創作者への対価は補償金・実績補償金に限られ、株式・新株予約権の記載はない。同ポリシーは知的財産センターが「保有する知的財産権を，地域企業及び大学発ベンチャー企業が利用しやすい条件の整備に努める」と定めるにとどまる。規則集の規程名一覧にも株式・新株予約権・出資に関する規程は存在しない。ライセンスポリシーPDFは埋め込みフォントのため本文を読み取れず未確認。', 'official', 'https://public2.legalcrud.com/yamaguchi_univ/act/110000221.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'pol_fund_investment', 'established', '外部ファンドと連携（大学の出資・自前VCはなし）', '山口フィナンシャルグループが設立した「Fun Fun Drive 投資事業有限責任組合」が山口大学の現役学生・教職員・卒業生を主な投資対象とし、大学は本取組の支援・運営を連携して行う。ただし大学自身がLP出資、ファンド組成、大学出資会社経由の投資を行う仕組みではなく、山口大学規則集にも出資・ファンドに関する規程は見当たらない。', 'official', 'https://web.archive.org/web/2021/http://www.yamaguchi-u.ac.jp/weeklynews/_7735/_8295.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_regulation_owner', 'not_started', '大学規程（国立大学法人の規則。認定規程は未制定）', '規則等の制定及び改廃の手続等に関する規則第2条第2号で「規則等」を学長が制定する学則・規則・規程・細則・内規・要項・申合せ等と定義しており、山口大学の規程はすべて国立大学法人山口大学の規則として整備される。学校法人規程ではない。ただし規則集の全編を通覧しても大学発ベンチャーの認定規程は存在せず、称号の根拠はウェブページ上の定義と登録運用にとどまる。', 'official', 'https://public2.legalcrud.com/yamaguchi_univ/act/110000060.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_review_body', 'unknown', null, '「山口大学発ベンチャー」の登録・削除・修正の窓口は学術研究部産学連携課産学連携係。ベンチャー起業支援室は山口大学産学公連携・研究推進センター規則第4条で同センターに置かれ、センターの管理運営に関する事項はセンター会議（同規則第5条）が審議する。ただし掲載可否を判定する認定委員会・審査会にあたる組織は公開情報に見当たらず、審査主体を断定できない。', 'official', 'https://public2.legalcrud.com/yamaguchi_univ/act/110000600.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_equity_decider', 'not_started', '規程なし（株式・新株予約権の取得制度が未整備）', '山口大学規則集の規程名一覧に株式・新株予約権・出資に関する規程はなく、知的財産ポリシー現行本文にも株式取得の記載がない。取得・処分を決裁する主体を定めた条項が確認できない。なお、よくある質問では教職員個人が自ら起業する会社へ出資・株式保有することは可能とされ、兼業・利益相反の観点から人事課服務管理係へ相談する扱いになっている（大学の取得とは別論点）。', 'official', 'https://public2.legalcrud.com/yamaguchi_univ/aggregate/catalog/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_amendment_decider', 'established', '学長制定（全学規則は役員会等三会議に付議）', '規則等の制定及び改廃の手続等に関する規則第2条第2号で「規則等」を学長が制定するものと定義。同条第3号で本法人の管理運営及び教育研究に関する事項で全学に関連する規則等は役員会、経営協議会又は教育研究評議会への付議を要するとし、他の部局等に影響を及ぼさない部局限りのものは付議不要。第4条で付議を要するものは会議開催予定日の3週間前まで、その他は施行希望日の2週間前までに総務部総務課へ書類を提出すると定める。', 'official', 'https://public2.legalcrud.com/yamaguchi_univ/act/110000060.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_post_grad_limit', 'established', '1年以内（他の職に就かなければ期限なし）', '「大学発ベンチャー」ページの定義で、本学職員若しくは学生が設立者である類型について「ただし，当該職員が退職又は学生が卒業等している場合は，その起業まで他の職に就かなかった場合又は起業までの期間が1年以内の場合に限る」と括弧書きしている。他の職に就いた場合の上限が1年。なおベンチャー起業支援室の相談対象は卒業年を問わず全卒業生・修了生（社会人入学者を含む）で、掲載要件とは範囲が異なる。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_renewal_rule', 'not_started', '規定なし（有効期間・更新手続の定めが公開情報にない）', '掲載の有効期間、更新の可否、届出方法を定めた記載は「大学発ベンチャー」ページにも山口大学規則集にもない。一方、レンタルスペースの利用期間は原則3年以内で「更新の際は審査が必要となります」と明記されており、施設利用の更新規定と称号の更新規定は別物として扱う必要がある。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_naming', 'established', '大学発ベンチャー（一覧見出しは「山口大学発ベンチャー企業紹介」）', '産学公連携・研究推進センターのページ名が「大学発ベンチャー」、一覧の見出しが「山口大学発ベンチャー企業紹介」、問い合わせ欄も「「山口大学発ベンチャー」に関して」と表記する。スタートアップの語はベンチャー起業支援室の紹介文（「山口大学からのスタートアッププレイヤーの輩出を促進します」）や山口フィナンシャルグループとの共同取組の発表で使われるが、称号としては用いていない。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_support_period', 'established', '支援ごとに別に定める（施設は原則3年以内・更新時審査）', '称号（掲載）そのものには期間の定めがなく、支援ごとに期間が置かれている。レンタルスペースのページは「利用期間 原則として，３年以内であり，更新の際は審査が必要となります」と明記。起業相談、知財相談、情報提供には期間の定めが見当たらない。', 'official', 'https://web.archive.org/web/20260216031356/http://kenkyu.yamaguchi-u.ac.jp/sangaku/?page_id=43', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_support_contents', 'unknown', null, '［自動検証で否認: 共用機器の記載が原文になく、機器使用は不可と回答］元の主張(established): 起業相談・知財相談・施設貸与（登記可）・共用機器・公的資金活用・金融機関連携。ベンチャー起業支援室の活動内容は、山口フィナンシャル・グループ専門家および山口ティー・エル・オーとの協働による起業支援、「志」イノベーション道場をハブとしたイベント開催、起業のための知財相談、各種情報の発信の4項目。よくある質問で国の競争的資金（研究開発型ベンチャー支援事業）等を活用した支援、新事業創出支援スペースの貸与と登記所在地利用を挙げる一方、起業にかかる費用や資本金への経費的支援はないと明記。共用機器は学外者として申請のうえ利用。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_yamaguchi', 'attr_source_docs', 'established', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/・https://web.archive.org/web/20251218185608/https:/…', '1本目が「大学発ベンチャー」の定義・掲載一覧・免責記載・問い合わせ窓口。2本目がベンチャー起業支援室の活動内容とよくある質問（登記、研究室機器、起業費用支援の可否）。3本目が山口大学産学公連携・研究推進センター規則で、第3条に技術移転及びベンチャー起業支援、第4条にベンチャー起業支援室の設置を定める。ベンチャー起業支援室とレンタルスペースの現行ページは学外から403が返るため、Internet Archiveの保存版を使用した。', 'official', 'https://www.yamaguchi-u.ac.jp/kenkyu/sangaku/chiiki/venture_company/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_cert_update', 'established', '認定日から5年・審査委員会の再審査で2年延長可', '文科省の量子科学技術研究開発機構部会（第11回、平成31年2月1日）資料1-1-2「QSTベンチャー支援制度の構造」の「認定／支援期間」欄に、①認定日より5年間、②認定ベンチャー企業より申請がある場合、審査委員会で再審査の上、2年間の認定期間（支援期間）延長が可能、と明記。公式サイトの認定ベンチャー一覧も各社の認定期間を開始日と終了日で表示している。要件の再確認は再審査の中で行われるが、規程本文は非公開のため条文番号は特定できない。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_title_restriction', 'unknown', null, 'QSTベンチャー支援制度規程の本文は公開されておらず、規程集ページ（一般管理・知的財産・人事・コンプライアンス等）にも掲載がない。制度紹介ページ「QSTベンチャー支援制度」と英語版ページはいずれも称号の使用範囲、使用停止、品質保証や投資推奨と誤認させない旨の条項を示していない。検索でも該当する要領・様式は確認できず、条項の有無を判断できない。', 'official', 'https://www.qst.go.jp/site/about-qst/1312.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_cancellation', 'unknown', null, '規程本文が非公開のため、取消事由・称号返付・表示削除・営業利用停止の定めを確認できない。公式サイトの「QSTベンチャー支援制度」ページは認定期間終了の3社を掲載しているが、これは期間満了の表示であり取消の運用を示すものではない。制度紹介ページ、英語版ページ、規程集のいずれにも取消条項の記載なし。', 'official', 'https://www.qst.go.jp/site/qst-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_report_change', 'established', '審査委員会への事業報告あり・変更届は非公開', '「第1期中長期目標期間終了時に見込まれる業務実績等報告書」に、ベンチャー審査委員会を年間平均4回開催し、認定希望ベンチャーの認定審査、兼業の可否の審査、認定ベンチャーの事業報告等を行った、と記載。認定後も事業報告を審査委員会へ上げる運用が確認できる。代表者・所在地・資本構成の変更届および解散時報告の定めは、規程本文が非公開のため確認できない。', 'official', 'https://www.qst.go.jp/uploaded/attachment/28300.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_support_request', 'established', '支援ごとの個別審査（兼業・出資は審査委員会）', '認定審査とは別に、ベンチャー審査委員会が「兼業の可否の審査」を行うことが第1期中長期目標期間終了時見込み業務実績等報告書に記載されている。出資については文科省部会資料1-1-2の「出資審査」欄が、出資予定先の財務状況・資産状況等の調査、ベンチャー審査委員会に設置する専門部会での審議、という個別手続を定める。施設の貸与・使用も有償で別途手続。支援申請書の様式および支援細則の本文は非公開。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_facility_registration', 'established', 'QST内居室の有償貸与・本店登記の可否は不明', '文科省部会資料1-1-2「3. QST施設の貸与等」に、QSTが有する研究施設等を貸与し、又は使用させることができる（ただし有償とする）と明記。一般企業には共用施設を条件付きで使用させるのみで居室等の貸付は行っていないが、認定ベンチャーには希望があれば共用施設の使用に加え居室等を貸付ける便宜が供与される、とある。商業登記（本店登記）の可否に触れた記載は公開資料に無い。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_vc_connection', 'established', 'VCセミナー・相談できる専門機関の紹介', '令和7年度業務実績等報告書に、VCによるQST全体の起業・研究の実装化を狙う研究者向けセミナーを開催（1月23日）し35名が参加、個別面談等を通じて事業化に向けたアドバイスを受けた、と記載。あわせて主務大臣評価の指摘への対応として、これまで連携実績のないVCと意見交換を行い認定ベンチャーが相談できる専門機関を増やした、とある。規程化された紹介制度ではなく産学連携部門の取組として運用されている。', 'official', 'https://www.qst.go.jp/uploaded/attachment/52142.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_eir', 'not_started', '客員起業家制度なし（支援は限定列挙）', '文科省部会資料1-1-2の「具体的な支援内容」は、①職員の兼業、②QST知財の実施許諾、③QST施設の貸与等、④認定ベンチャーへの出資、の4項目の限定列挙で、客員起業家や起業家メンターの招聘は含まれない。令和7年度業務実績等報告書が新規支援として挙げるのも展示会での事業紹介とVCとの意見交換にとどまる。産学連携ページにもEIRの記載はない。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_cxo_pool', 'not_started', '経営人材紹介の制度なし（人的支援は兼業・出向）', '支援メニュー上の人的支援は、QST職員が認定ベンチャーの責任者・役員へ兼業または出向する形に限られる（令和7年度業務実績等報告書「QST認定ベンチャーへの兼業・出向により得られる収入等の取扱いについて規程を改正し、役員として兼業する職員が報酬を得ることを可能とした」）。外部のCEO/CXO候補を紹介・マッチングする仕組みは公開資料に無く、文科省部会資料の支援内容4項目にも含まれない。', 'official', 'https://www.qst.go.jp/uploaded/attachment/52142.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_ip_equity', 'established', '知財実施許諾の対価として普通株式を取得', '令和7年5月9日のQSTプレス発表に、リチウム回収技術に関するQST知財をLiSTieへ実施許諾する対価として、LiSTieから普通株式を取得するというスキーム、と明記。文科省部会資料1-1-2の出資業務でも、出資方法として金銭による出資又は現物出資が認められている。新株予約権（ストックオプション）の取得可否は公開資料では確認できない。', 'official', 'https://www.qst.go.jp/site/press/20250509.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'pol_fund_investment', 'established', '機構による直接出資（ファンド組成なし）', 'QST法第16条第8号により、科学技術・イノベーション創出の活性化に関する法律第34条の6第1項の規定による出資業務を実施。文科省部会資料1-1-2は、出資対象をQST認定ベンチャーの認定を受ける資格を持つ株式会社に限定し、原資を知財ライセンス収入・寄附収入と定める。第1期中長期目標期間終了時見込み報告書によれば、ベンチャー審査委員会の下に出資等検討部会を設置し令和4年3月に初回会議を実施。大学VC・LP出資・指定ファンドの仕組みは無い。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_regulation_owner', 'established', '研究機関規程（QSTベンチャー支援制度規程）', '文科省部会資料1-1-2の欄外に「設置規程類：QSTベンチャー支援制度規程、QSTベンチャー審査委員会設置細則ほか」と記載され、国立研究開発法人QSTの内部規程として整備されている。第1期中長期目標期間終了時見込み業務実績等報告書にも、平成28年度にQSTベンチャー支援規程を始め制度を整備し、平成29年度より運用を開始した、とある。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_review_body', 'established', 'QSTベンチャー審査委員会（出資は出資等検討部会）', '文科省部会資料1-1-2に「審査委員会による認定基準」と記載され、設置根拠として「QSTベンチャー審査委員会設置細則」が挙げられている。出資審査は「QSTベンチャー審査委員会に設置する専門部会（新設）での審議（専門部会は外部有識者複数名及びQSTの役職員1名により構成）」とある。第1期報告書は同部会を出資等検討部会と呼び、令和4年3月に初回会議を実施。委員会は年間平均4回開催。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_equity_decider', 'established', '理事会議等の審議を経て決定', '文科省部会資料1-1-2「量子科学技術研究開発機構（QST）の出資業務について」の出資決定欄に「理事会議等における審議を経て、可否を決定」と明記。その前段として、出資予定先の財務状況・資産状況等の調査と、ベンチャー審査委員会に設置する専門部会での審議を経る。取得済み株式の処分についての決裁者は公開資料では確認できない。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_amendment_decider', 'unknown', null, 'QSTベンチャー支援制度規程の本文が非公開で、改廃条項を確認できない。規程集で公開されている利益相反マネジメント規程は第7条（規程の改正）で「委員会の審議を経て改正するものとする」と定めるが、これは同規程固有の定めであり、ベンチャー支援制度規程に適用されるとは限らない。', 'official', 'https://www.qst.go.jp/uploaded/attachment/45272.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_post_grad_limit', 'not_started', '規定なし（対象は職員が設立する企業）', '文科省部会資料1-1-2の「支援の対象」は、①QSTが開発した研究開発成果の普及・実用化により社会還元を行う企業、②QSTに正当な対価を支払い研究開発活動を一層推進することに貢献する企業、③上記目的の達成のためQSTの職員が設立しようとする企業、の3項目の限定列挙。退職者や修了者を対象に含める規定も、退職後の年限も記載されていない。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_renewal_rule', 'established', '更新可（審査あり）・再審査で2年延長', '文科省部会資料1-1-2の「認定／支援期間」欄に、認定ベンチャー企業より申請がある場合、審査委員会で再審査の上、2年間の認定期間（支援期間）延長が可能、と明記。延長は企業側の申請を起点とし、審査委員会の再審査を要する。届出のみで更新される仕組みではない。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_naming', 'established', '独自名称：QST認定ベンチャー', '公式サイトの制度名は「QSTベンチャー支援制度」、企業に付与される称号は「QST認定ベンチャー」。文科省部会資料1-1-2、令和7年度業務実績等報告書、令和7年5月9日プレス発表のいずれも「QST認定ベンチャー」の表記を用いる。大学発ベンチャー・大学発スタートアップといった一般名称は使用していない。', 'official', 'https://www.qst.go.jp/site/qst-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_support_period', 'established', '称号期間と同じ（認定＝支援期間）', '文科省部会資料1-1-2は当該欄を「認定／支援期間」とひとまとめに表記し、延長についても「2年間の認定期間（支援期間）延長が可能」と記す。認定期間と支援期間を別に定めてはいない。ただし施設の貸与・使用や出資は個別の契約・手続によるため、個々の支援が続く期間は各契約で定まる。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_support_contents', 'established', '兼業許可・知財の独占実施許諾・施設貸与・共用設備使用・出資・共同研究・VC紹介', '文科省部会資料1-1-2の「具体的な支援内容」は、職員の兼業（責任者への兼業可、役員兼業の時間制約緩和）、QST知財の再実施権付き独占的実施許諾、QST施設の貸与等（有償、共用施設に加え居室等の貸付）、認定ベンチャーへの出資（金銭・現物）の4項目。同資料の出資頁は出資以外の支援策として共同研究の実施も挙げる。令和7年度業務実績等報告書は、展示会での認定ベンチャーの事業紹介を新規支援として追加した旨を記載。', 'official', 'https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfile/2019/02/08/1413452_002.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_qst', 'attr_source_docs', 'established', 'https://www.qst.go.jp/site/qst-venture/・https://www.mext.go.jp/b_menu/shingi/kokurituken/010/shiryo/__icsFiles/afieldfi…', '制度の骨格（対象・認定基準・期間・支援内容・出資手続）は文科省の量子科学技術研究開発機構部会 資料1-1-2が最も詳しい。現在の認定企業一覧と認定期間は公式サイトのQSTベンチャー支援制度ページ。直近の運用実績（兼業報酬を認める規程改正、LiSTie社への出資、VCセミナー、展示会での事業紹介）は令和7年度業務実績等報告書。規程本文PDFは公開されていない。', 'official', 'https://www.qst.go.jp/site/qst-venture/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_cert_update', 'not_started', '認定制度なし。施設使用は2月前申請で更新可', '京都大学規程集および成長戦略本部（IAC）の支援メニュー一覧（12件の限定列挙）に、大学発ベンチャーの認定・称号付与とその有効期間・更新審査を定めた規程は存在しない。期間と更新が定められているのは施設使用側で、京都大学国際科学イノベーション棟規程第7条第2項が長期使用施設の使用期間を「事業期間の範囲内で統括管理者が認める期間」とし、同条第3項が使用期間満了日の2月前までの申請書提出による更新を定める。認定要件の再確認に相当する手続きは確認できない。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001349.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_title_restriction', 'established', '大学名・ロゴ使用は許可制、原則教職員限定', '「名称・ロゴ等の使用について」ページで、名称は「京都大学」「京大」「Kyoto University」の3種とされ、エンブレム・ロゴ・スクールカラーの使用は原則として教職員に限られる。学外者は教育研究上の関係がある場合に、関係教職員・部局を経由して広報室へ申請し、可否判断に2か月以上を要する。品質保証や大学の推奨と誤認させる使用を明文で禁じる条項は本ページでは確認できなかった。称号制度自体が存在しないため、称号の使用範囲・使用停止の規定もない。', 'official', 'https://www.kyoto-u.ac.jp/ja/about/operation/symbol/name', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_cancellation', 'not_started', '認定取消なし。施設使用許可の取消のみ規定', '認定・称号制度がないため、取消事由・称号返付・表示削除・営業利用停止を定めた条項は存在しない。取消規定があるのは施設使用側で、京都大学国際科学イノベーション棟規程第13条第1項が使用許可の取消事由を7号列挙し、同条第2項で取消による損害について大学は責めを負わないとする。第16条は使用終了時の原状回復義務と、履行しない場合に統括管理者が代行できることを定める。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001349.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_report_change', 'not_started', '認定の年次報告・変更届なし。施設は変更許可制', '認定制度がないため、事業報告・決算の年次提出、代表者・所在地・資本構成の変更届、解散時報告を課す規定は確認できない。近い手続きは施設使用側にあり、京都大学国際科学イノベーション棟規程第9条第5項が、許可後に使用期間や使用内容を変更するとき、または使用を取り止めるときは速やかに統括管理者へ申し出て許可を受けなければならないと定める。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001349.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_support_request', 'established', '施設・資金とも個別申請と審査（募集要項あり）', '認定とは別に、支援ごとの申請・審査が制度化されている。京都大学国際科学イノベーション棟規程第9条は長期・一時とも統括管理者への使用申請と許可を義務づけ、長期使用施設は第20条の運営委員会の議を経て決定する。ベンチャーインキュベーションセンター（KUViC）は募集要項と入居申込書を配布し、入居希望の2か月前提出、申込から入居承認まで約2か月の審査を要する。登記事項証明書・住民票等の添付書類も指定されている。資金支援もKSAC-GAPファンド、IPG-Advance、三菱商事Startup Catapultが各々の公募採択を持つ。', 'official', 'https://iac.kyoto-u.ac.jp/info/cat-8/if08-09/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_facility_registration', 'unknown', null, '［自動検証で否認: 登記可・入居資格が該当頁に記載なし］元の主張(established): KUViC入居可、入居中に限り本店登記可。ベンチャーインキュベーションセンター（KUViC）は国際科学イノベーション棟1階の起業前チーム・創業直後スタートアップ向け施設で、個室・半個室とフリーアドレス席、WiFi・会議室・カフェコーナーを備える。「本部機能をキャンパス内に置き研究者と密に連携できる」ことを目的とし、住所利用として会社の登記も可能だが、入居期間中に限られると明記されている。入居資格は、京大の研究成果を活用し設立5年未満の法人、または入居後3年以内に会社設立を予定し研究成果の事業化に取り組む個人。施設使用は有償。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_vc_connection', 'unknown', null, '［自動検証で否認: 日本VC社との連携を検索でも確認できず］元の主張(established): 京都iCAPと連携VCへの接続を支援メニュー化。成長戦略本部（IAC）のスタートアップ支援メニューに「京都大学関連ベンチャーファンド」が独立項目として置かれ、大学が子会社の京都大学イノベーションキャピタル株式会社（京都iCAP）にファンド運営を委託・出資する体制と、日本ベンチャーキャピタル株式会社との連携が示されている。KUViC入居者は成長戦略本部と京都iCAPのスタッフと日常的にやりとりする運用。金融機関・自治体への紹介導線は公開ページでは確認できなかった。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_eir', 'established', '京都iCAPが直接雇用型EIR（EIR-iCAP）を運営', 'IACのNEWS & TOPICS「京都大学イノベーションキャピタル株式会社が『客員起業家（EIR）活用に係る実証事業』に採択されました」で、京都iCAPが同事業を活用し、京都iCAPによる直接雇用を行うEIRプログラム「EIR-iCAP」をローンチしたと公表。実証事業は経済産業省2021年度補正予算、受託は一般社団法人社会実装推進センター（JISSUI）、募集要項は2022年7月21日付。あわせて起業家候補者クラブECC-iCAPがフルタイム／パートタイムのEIRとして創業準備を行うコミュニティを運営する。大学規程ではなく100%子会社のプログラムとして運用されている点に注意。', 'official', 'https://iac.kyoto-u.ac.jp/news-topics/1112/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_cxo_pool', 'established', 'ECC-iCAPで経営人材と研究シーズをマッチング', '京都iCAPが運営するECC-iCAP（起業家候補者クラブ）は、教員によるリバースピッチ、創業前プロジェクトのピッチ、アルムナイイベント、セミナーで研究者・創業前プロジェクトと経営人材候補を引き合わせる「出会い」、フルタイム／パートタイムEIRとして創業準備を進める「紡ぎ」、投資検討・顧客接続・経営陣採用支援・海外展開支援を行う「巣立つ」の3段階で構成される。起業経験や専門性は必須とせず意志と覚悟を要件とする。大学本体の規程ではなく子会社のプログラム。', 'official', 'https://www.ecc.kyoto-unicap.co.jp/what-we-do/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_ip_equity', 'established', 'ライセンス対価として株式・新株予約権を取得可', '京都大学におけるライセンス等の対価として取得する株式等取扱規程（平成24年3月6日総長裁定、令和7年3月25日改正）が正面から定める。第4条第1項で、成長戦略本部長はライセンス等の対価として大学発ベンチャー企業から株式等を取得しようとするとき、当該企業の財務状況その他取得の妥当性を判断するために必要な事項を審査し、取得の可否を決定する。第2条第4号は大学発ベンチャー企業を「大学の研究成果を基に起業したベンチャー企業、大学との共同研究により起業したベンチャー企業その他大学と関連のあるベンチャー企業」と定義する。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001283.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'pol_fund_investment', 'established', '100%子会社の京都iCAPが投資、大学が出資', '京都大学イノベーションキャピタル株式会社（京都iCAP）は京都大学の100%出資により2014年12月に設立された子会社で、京都大学に属する研究者の研究成果・技術等を事業化する企業への出資その他の支援を行う。ECC-iCAP、EIR-iCAP、投資事業の3本立てで運営。IACの「京都大学関連ベンチャーファンド」ページは、大学が京都iCAPにファンド運営を委託・出資する構図と日本ベンチャーキャピタル株式会社との連携を示す。個別ファンド名・規模や、出資の根拠となる学内規程名は公開ページでは確認できなかった。', 'official', 'https://www.kyoto-unicap.co.jp/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_regulation_owner', 'established', '大学規程（達示および総長裁定）', '国立大学法人京都大学の規程集で確認。京都大学成長戦略本部規程は達示第10号として制定（令和6年4月1日施行、令和7年3月17日達示第3号改正、令和8年3月24日達示第8号改正・令和8年4月1日施行）。株式等取扱規程は総長裁定として制定・改正されている。いずれも大学（国立大学法人）自身の規程で、学校法人規程や別法人の規程ではない。ただし大学発ベンチャーの認定規程そのものは存在しない。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001507.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_review_body', 'established', '成長戦略本部（認定専門の委員会は不設置）', '京都大学成長戦略本部規程で、本部長は総長が指名し任期2年以内（第3条）、副本部長は本部長が指名し総長が委嘱（第4条）、運営協議会は財務・渉外・産官学連携担当理事と本部長・副本部長で構成される（第5条〜第11条）。株式等取得の審査・決定は成長戦略本部長が行う（株式等取扱規程第4条第1項）。施設については国際科学イノベーション棟規程の統括管理者と、第20条の運営委員会が長期使用施設の可否を審議する。大学発ベンチャーの認定委員会・審査会は置かれていない。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001507.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_equity_decider', 'established', '成長戦略本部長（株式等取扱規程第4条）', '株式等取扱規程第4条第1項は、成長戦略本部長がライセンス等の対価として大学発ベンチャー企業から株式等を取得しようとするとき、当該企業の財務状況その他株式等の取得の妥当性を判断するために必要な事項を審査し、取得の可否を決定すると定める。処分（売却）の決裁者は本文に明記されておらず、第6条が「この規程に定めるもののほか必要な事項は、別途本部長が定める」としているため、本部長の別定に委ねられている。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001283.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_amendment_decider', 'established', '総長（達示・総長裁定による制定改廃）', '株式等取扱規程は平成24年3月6日総長裁定で制定され、令和7年3月25日の改正も総長裁定によるため、改廃権は総長にある。成長戦略本部規程は達示（第10号、改正は達示第3号・第8号）で制定改廃される。国際科学イノベーション棟規程は第22条で、総長が使用者の同意を得ることなく規程を変更できるとし、変更時は効力発生日までに相当な期間をおいてホームページ掲示または通知を要すると定める。役員会・教育研究評議会の議決を要する旨の記載は各規程本文では確認できなかった。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001283.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_post_grad_limit', 'established', '関連性で判断（研究成果との関連で定義）', '株式等取扱規程第2条第4号は大学発ベンチャー企業を「大学の研究成果を基に起業したベンチャー企業、大学との共同研究により起業したベンチャー企業その他大学と関連のあるベンチャー企業」と定義し、退職・卒業・修了からの経過年数を要件にしていない。KUViCの入居資格も、京大の研究成果を活用し設立5年未満の法人、または入居後3年以内に会社設立を予定する個人という形で、法人の設立年数と設立予定時期で切られており、在籍終了からの年限ではない。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001283.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_renewal_rule', 'not_started', '規定なし（称号認定制度そのものが不存在）', '認定・称号制度がないため、その更新の可否と方法を定めた規定は存在しない。更新規定があるのは施設使用側で、国際科学イノベーション棟規程第7条第3項が使用期間満了日の2月前までに申請書を提出することで更新申請できると定める（審査あり・運営委員会の議を経る長期使用施設の場合）。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001349.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_naming', 'not_started', '称号なし（規程上「大学発ベンチャー企業」の定義のみ）', '成長戦略本部（IAC）のスタートアップ支援メニューは起業支援プログラム、KSAC-GAPファンド、IPG-Advance、三菱商事Startup Catapult、関連ベンチャーファンド、起業相談、交流の場、KUEP、EP LAB、KUViC、MIC、イノベーションハブ京都の限定列挙で、認定称号の授与は含まれない。学内規程で「大学発ベンチャー企業」の語が現れるのは株式等取扱規程第2条第4号の定義規定のみで、称号として付与・表示させる仕組みではない。', 'official', 'https://iac.kyoto-u.ac.jp/info/cat-1/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_support_period', 'established', '支援ごとに別に定める（プログラム単位で期間設定）', '称号がないため称号期間という概念がなく、期間は支援ごとに定まる。起業支援プログラムのページは「事業化フェーズごとに支援金額、支援年数の異なる複数のプログラムを運営している」と明記する。施設は国際科学イノベーション棟規程第7条第2項で長期使用施設の使用期間を「事業期間の範囲内で統括管理者が認める期間」とし、6月以上の事業を長期使用の対象とする。KUViCの募集要項では入居の通算上限が別に置かれている。', 'official', 'https://iac.kyoto-u.ac.jp/info/cat-1/if01-02/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_support_contents', 'unknown', null, '［自動検証で否認: 本店登記・共用機器が一次資料に記載なし］元の主張(established): 施設・本店登記・共用機器・起業相談・資金・VC接続・起業家教育・交流。成長戦略本部（IAC）「京都大学のスタートアップ支援の概要」に列挙された12メニューを整理した。施設はKUViC・メディカルイノベーションセンター（MIC）・イノベーションハブ京都・EP LAB、資金はKSAC-GAPファンド・IPG-Advance・京都大学三菱商事Startup Catapult、接続は京都大学関連ベンチャーファンド、相談は起業相談、教育・交流はKUEPと起業をめざす人たちの交流の場。本店登記はKUViC入居期間中に限り可能。知財・広報の専用メニューは同ページには置かれていない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_0278b48721bd', 'attr_source_docs', 'established', '株式等取扱規程・国際科学イノベーション棟規程・IAC支援メニュー', '制度の中身を読むうえで最も情報量が多い3本。株式等取扱規程はライセンス対価の株式取得と大学発ベンチャーの定義、成長戦略本部長の決裁権を定める。国際科学イノベーション棟規程は施設の申請・許可・期間・更新・取消・原状回復・使用料を条文で定める唯一の支援規程。IACの支援メニュー一覧は認定制度がないことと支援12件の全体像を確認できる。補助として成長戦略本部規程（w002RG00001507）が組織と審議体を定める。', 'official', 'https://www.kyoto-u.ac.jp/uni_int/kitei/reiki_honbun/w002RG00001283.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_cert_update', 'established', '支援期間は3年以内、更新規定なし・再申請可', '大学発スタートアップ支援規則（令和7年2月13日制定、令和7年3月1日施行）第7条（支援期間）「3年を超えない範囲で、センター長が必要と認める期間」とし、「再申請を妨げない」と規定。期間満了時の更新審査や要件の再確認手続きは条文になく、継続を望む場合は第5条の申請からやり直す建て付け。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_title_restriction', 'unknown', null, '［自動検証で否認: 称号制度がないのにestablishedで免責条項を代用］元の主張(established): 免責条項で品質・経営状況の非保証を明記。支援規則第8条（免責）に「製品、サービス等の内容及び品質並びに経営状況を保証するものではない」と明記し、支援または支援の中止により損害が生じても賠償義務を負わないと規定。保証誤認の防止条項としては機能するが、KITは称号を付与する制度を持たないため、称号の使用範囲や使用停止の規定は存在しない。大学名・ロゴの使用に関する条項も支援規則本文にない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_cancellation', 'established', '中止事由6類型を規定、中止後の措置は規定なし', '支援規則第10条（支援の中止）が中止事由を列挙。事業活動が支援条件から著しく逸脱した場合、社会的信用を失墜させる行為、企業活動の実態喪失、報告書の未提出、代表者からの申出、その他適当でないと認める場合の6類型。産学公連携推進センター運営委員会の議を経て決定し、代表者に通知する。称号の返付、表示の削除、営業利用の停止といった中止後の処理は条文にない（称号制度自体がないため）。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_report_change', 'established', '年次の事業報告書・収支決算書提出、解散等は速やかに報告', '支援規則第9条（事業報告書等の提出）。年度ごとに決算日から3月以内に事業報告書および収支決算書を提出する義務を課す。解散、破産手続、再生手続、更生手続の開始や不正競争に係る罰金の確定時は速やかに報告することも規定。一方、代表者・所在地・資本構成の変更届は条文になく、未整備。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_support_request', 'established', '申請書でセンター長に申請、推進室審査・委員会の議で決定', '支援規則第5条（支援の申請）で申請書を提出して産学公連携推進センター長に申請すると規定。第6条（支援の決定及び通知）で、施設貸与・商業登記はスタートアップ推進室の審査と産学公連携推進センター運営委員会の議を経て決定、知財ライセンスは加えて知的財産戦略室の審査、株式取得は株式等取扱規則に基づき決定。結果は文書で申請者へ通知。支援の種類ごとに審査経路が分かれる個別審査型。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_facility_registration', 'established', '学内施設の貸与と貸与施設を所在地とする商業登記を許可', '支援規則第3条（支援内容）が「施設を貸与すること」「商業登記を認めること」を支援メニューの第1号・第2号として明記。第6条により両者ともスタートアップ推進室の審査と産学公連携推進センター運営委員会の議を経てセンター長が決定する。期間は第7条により3年以内。支援内容に応じて一定の対価を求めうる建て付け。本店登記まで規則本文で明文化している点が特徴。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_vc_connection', 'established', 'KSAC共同機関としてVC・金融機関・自治体と接続', 'KSAC（関西スタートアップアカデミア・コアリション）の参画機関一覧で、国立大学法人京都工芸繊維大学は共同機関（大学25校のうち1校）に位置づけ。KSACの協力機関には銀行、ベンチャーキャピタル、商工会議所、自治体9機関が含まれ、Demo Dayを通じて金融機関やVC、大手企業等との連携をめざすと記載。ただしKIT単独の支援規則・スタートアップ推進室規則にはVCや金融機関への紹介・接続の条項はない。', 'official', 'https://ksac.site/participation/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_eir', 'not_started', '客員起業家・起業家招聘の制度なし', '支援規則第3条の支援内容は施設貸与・商業登記・知財ライセンス優遇・株式等受入れの限定列挙で、客員起業家の招聘はない。スタートアップ推進室規則第2条の業務も起業マインド醸成、起業シーズの発掘育成、啓発・相談対応、起業時の伴走支援の4分野で、EIRや起業家メンターの招聘は含まれない。産学連携本部のスタートアップ支援ページも相談員は本学准教授2名のみで、外部起業家の招聘制度の記載なし。KSAC側の事業一覧にもEIRは挙がっていない。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000201.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_cxo_pool', 'established', 'KSACのCXO候補マッチング事業を利用可能', 'KSACの参画機関ページに主要事業として「CXO候補マッチング事業」が明記され、京都工芸繊維大学は共同機関として参画（令和8年8月時点で参画105機関、主幹機関は京都大学）。経営人材の紹介はこの広域連携の枠組みで提供される。KIT単独の支援規則およびスタートアップ推進室規則には経営人材の紹介・マッチングに関する条項はない。', 'official', 'https://ksac.site/participation/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_ip_equity', 'established', 'ライセンス対価として株式・新株予約権を取得可', '「ライセンス等の対価として取得する株式等取扱規則」（令和7年2月13日制定、令和7年3月1日施行）。第4条でスタートアップ推進室が事業計画の蓋然性、資金提供の可能性、イグジット潜在性、株式等の種類・数量・行使価格等を審査し、知的財産戦略室が知的財産権の価値と市場規模等を総合審査。第5条で産学公連携推進センター長が運営委員会の議を経て取得の可否を決定し、学長へ報告。支援規則第3条第4号にも「株式及び新株予約権を受け入れること」を支援メニューとして規定。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000062.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'pol_fund_investment', 'not_started', '大学VC・出資・ファンド組成の規程なし', '支援規則第3条の支援内容は施設貸与、商業登記、知財ライセンスの優遇的条件、株式および新株予約権の受入れの4号とセンター長が認めるその他で構成され、大学からの出資やファンドへのLP出資は含まれない。株式取得はあくまでライセンス対価としての受入れであり、資金の払込みを伴う投資ではない。KIT自身の大学VCや出資会社に関する規程は規程集に見当たらない。資金面はKSAC-GAPファンド（JST事業）という外部プログラムに依存。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_regulation_owner', 'established', '大学規程（国立大学法人の学内規則）', '「国立大学法人京都工芸繊維大学における大学発スタートアップの支援に関する規則」として国立大学法人が定める学内規則。関連する「ライセンス等の対価として取得する株式等取扱規則」「産学公連携推進センタースタートアップ推進室規則」も同じ令和7年2月13日制定・3月1日施行で、いずれも法人の規則として規程集（Reiki-Base）に収録。学校法人規程や外部団体の規程ではない。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_review_body', 'established', '産学公連携推進センター運営委員会（審査はスタートアップ推進室）', '支援規則第6条により、施設貸与・商業登記はスタートアップ推進室の審査と産学公連携推進センター運営委員会の議を経て決定。知財ライセンスは加えて知的財産戦略室が審査。決定権者は産学公連携推進センター長。第10条の支援中止も同運営委員会の議を経る。単独の「認定委員会」は存在しない。事務は第11条により研究推進・産学連携課が行う。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_equity_decider', 'established', '産学公連携推進センター長（運営委員会の議、学長へ報告）', '株式等取扱規則第5条第1項「センター長は、審査及び産学公連携推進センター運営委員会の議を経て、株式等の取得の可否を決定する」。同条第3項で決定後に学長へ報告。取得後の管理は第7条により学長が管理させる。処分（売却）については第12条で利益相反マネジメント委員会において確認の上で実施すると規定しており、取得と処分で決裁経路が分かれる。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000062.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_amendment_decider', 'unknown', null, '支援規則第12条は「この規則に定めるもののほか必要な事項は、委員会の議を経て、学長が定める」とするのみで、規則自体の制定改廃の決裁者を定めた条項はない。株式等取扱規則第14条も同じ書きぶり。役員会規則第3条の審議事項は中期目標の意見、国立大学法人法に基づく認可・承認事項、予算・決算、重要な組織の設置廃止変更、その他学長が定める重要事項の5号で、規則の制定改廃を明示する号がない。公開情報からは改廃主体を特定できない。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000012.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_post_grad_limit', 'established', '3年以内（退職等から3年以内の設立に限定）', '支援規則第2条（定義）。大学発スタートアップは、本学の知的財産権や研究成果に基づく起業であること、かつ職員等または学生が発起人であることの両方を満たす企業とし、離籍者については退職等から3年以内の設立に限ると規定。研究成果要件と人的要件の両方を課す点で対象範囲は狭い。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_renewal_rule', 'established', '更新不可・再申請（3年以内、再申請を妨げない）', '支援規則第7条（支援期間）「支援の期間は、3年を超えない範囲で、センター長が必要と認める期間とする」「再申請を妨げない」。更新という手続き概念を置かず、期間満了後は第5条の申請と第6条の審査・決定を再度経る建て付け。届出のみで延長する簡略経路はない。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_naming', 'established', '大学発スタートアップ（規則上の呼称。称号付与はしない）', '支援規則の題名および第2条の定義で「大学発スタートアップ」の語を用いる。ただしこの規則は支援の可否を決める制度であり、企業に称号を付与して名乗らせる建て付けではない。第8条の免責規定も品質・経営状況の非保証を述べるのみで、称号の使用範囲や表示方法の規定はない。認定企業一覧の公開も確認できない。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_support_period', 'established', '支援ごとに別に定める（3年以内でセンター長が決定）', '支援規則第7条で、支援期間は3年を超えない範囲でセンター長が必要と認める期間と規定し、案件ごとに個別に定める。称号制度を持たないため称号期間という概念自体がなく、期間は支援そのものの有効期間として設定される。第6条により支援の決定は文書で申請者へ通知されるため、期間もその通知で確定する。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_support_contents', 'established', '施設貸与・商業登記・知財ライセンス優遇・株式等受入・起業相談・GAPファンド', '支援規則第3条が支援内容を、施設を貸与すること、商業登記を認めること、知的財産権のライセンス等に関する優遇的条件、株式および新株予約権を受け入れること、その他センター長が認める支援、と列挙。加えて産学連携本部のスタートアップ相談室が実務家教員2名によるデザイン思考・事業化・資本政策・IPO/M&A等の相談に対応。資金と経営人材はKSAC共同機関としてKSAC-GAPファンドおよびCXO候補マッチング事業を利用する構造。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_2055e944ae82', 'attr_source_docs', 'established', '大学発スタートアップ支援規則・株式等取扱規則・スタートアップ推進室規則', '制度の中核は支援規則（u042RG00000061）で、定義・支援内容・申請・決定・期間・免責・報告・中止まで一通りを収める。株式・新株予約権の取得手続きは株式等取扱規則（u042RG00000062）が正本。実施組織と業務範囲はスタートアップ推進室規則（u042RG00000201）。相談窓口の実務は産学連携本部のスタートアップ支援ページ、資金と経営人材はKSACの参画機関ページで確認できる。', 'official', 'https://www.kit.ac.jp/01/reiki_int/reiki_honbun/u042RG00000061.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_cert_update', 'established', '認定期間5年／2年、再申請による延長可', '認定規程第4条第6項。第2条第1号ア（知的財産活用型）は認定の日から5年間、同号イ（教職員・学生等設立）は2年間。ただし書で「再申請による延長を妨げない」と定める。更新は自動ではなく第4条第1項からの申請手続を再度踏む形。第4条第7項で認定時の申請内容に変更が生じたときは申請内容変更届出書を提出し、第8項から第10項で審査委員会が点検・評価し、重要な変更なら再審査、不認定なら第11条で取消。要件の再確認が期中にも働く構造。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_title_restriction', 'established', '品質・経営状況を保証しない旨を明記、称号使用は認定期間まで', '認定規程第8条（免責）が「認定により製品、サービス等の内容及び品質並びに経営状況を保証するものではなく」と明記。第5条第5号は申請条件として「自社の製品、サービス等の内容及び品質を保証するために認定を受けるものではないこと」を課す。第6条第2項で称号は当該大学名を冠する形に限定、第3項でロゴマーク使用可、第4項で使用期間を認定期間の末日までに限定。第9条は称号の使用により法人に損害を与えた場合の損害賠償義務を定める。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_cancellation', 'established', '取消事由を列挙、称号と便宜措置は同時失効、事後利用禁止', '認定規程第11条。第1項は直ちに取り消す事由7号（該当性喪失、活動実態なし、認定解除申出書の提出、事業報告の未提出、第10条第2項の報告、理事会の不認定決定、反社会的勢力該当）を列挙。第2項は意見聴取を経て理事会が可否を審議する事由5号。第3項で認定取消通知書により通知し、称号の授与等と便宜措置は取消に伴い同時に効力を失い、通知書受領日以降は認定を受けた事実を事業に使用・利用してはならないと定める。第12条が意見聴取の期日通知・陳述書提出・資料閲覧の手続を規定。称号記の物理的な返付を求める条文は無い。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_report_change', 'established', '決算日から3か月以内の事業報告、申請内容変更届出書', '認定規程第10条（現状報告）第1項で、代表者は毎年、認定ベンチャーが定めた決算日から3か月以内に事業報告（様式第8号）で活動状況を理事長へ報告。様式第8号は直近事業年度の貸借対照表・損益計算書の写しの添付欄を持つ。第2項は不正競争防止法違反の処罰、民事再生・会社更生・破産の各手続、会社法の解散、消費者保護法令違反の行政処分等に該当したとき、代表者・清算人・管財人が速やかに報告する義務を定める。認定内容の変更は第4条第7項の申請内容変更届出書（様式第3号）。代表者・所在地・資本構成を個別に名指しした変更届の条文は無く、申請書記載事項の変更として包括的に扱う。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_support_request', 'established', '便宜措置申請書を学長へ提出、認定とは別に審査', '認定規程第7条第3項。認定ベンチャーの代表者は便宜措置申請書（様式第5号）を称号授与大学の学長へ提出し、内容変更は便宜措置変更申請書（様式第6号）。第4項で学長が必要に応じ措置を講じ、便宜措置通知書（様式第7-1号）または不承認の通知書（様式第7-2号）で代表者へ通知する。様式第5号は第1号施設貸与、第2号商業登記許可、第3号研究設備等利用許可、第4号その他のチェックボックス形式。理事長・理事会が行う認定審査とは決裁ラインが分かれ、便宜措置は学長決裁。独立した支援細則は規程集に見当たらない。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_facility_registration', 'established', '事務室・研究室の貸与と貸与施設での商業登記許可', '認定規程第7条第1項。第1号で事務室又は研究室として称号授与大学内の施設を貸与、第2号で貸与した施設について貸与期間中における認定ベンチャーの所在地とする商業登記を許可、第3号で研究設備等の利用許可、第4号でその他学長が必要と認めること。いずれも大学の管理・運営及び教育・研究・診療等に支障が生じない範囲内という限定付き。インキュベーション施設としての専用棟の記載は公開情報に無く、学内の既存施設の貸与という形。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_vc_connection', 'established', 'KSAC参画、Demo Day等でVC・金融機関と接続', '京阪神スタートアップ アカデミア・コアリション（KSAC）の参画機関一覧に「京都府公立大学法人 京都府立医科大学」が共同機関（大学）として掲載。KSACの支援事業ページは、GAPファンド採択案件の成果発表の場としてDemo Day等を開催し金融機関・VC・大手企業との連携をめざすと記載。学内では研究支援課がKSAC-GAPファンド（JST大学発新産業創出基金事業）を公募している。一方、大学単独のVC紹介制度、提携VC、地域金融機関との連携協定は認定規程・産学連携ページ・K-MICSページのいずれにも記載が無い。', 'official', 'https://ksac.site/activity/corporate/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_eir', 'not_started', '制度なし（規程・支援メニューに記載なし）', '認定規程第7条の便宜措置は施設貸与・商業登記許可・研究設備利用許可の3号とその他学長が認めるもので、人材招聘の記載は無い。産学公連携機構K-MICSの支援メニューは人材育成・交流（覚生塾）、社会実装支援、研究環境整備、技術相談、共同研究、受託研究、寄附講座、特任教員、知的財産、利益相反の限定列挙で、客員起業家・起業家メンターの項目は無い。KSACの支援事業一覧にもEIRの記載は無い。法人規程一覧にも該当規程が無い。', 'official', 'https://www.kpu-m.ac.jp/doc/alliance/sangakukou.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_cxo_pool', 'established', 'KSACのCXO候補マッチング事業を利用可', 'KSACの支援事業として、別サイトECP-KANSAIで展開するCXO候補マッチング事業が挙げられている。京都府立医科大学はKSACの共同機関（大学）として参画機関一覧に掲載されているため、この経路での経営人材紹介が利用対象となる。ただし大学自身の公開ページ（産学連携、K-MICS）および認定規程には、経営人材の紹介・マッチングを大学の制度として定めた記載は無く、学内独自の人材プールは確認できない。', 'official', 'https://ksac.site/activity/corporate/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_ip_equity', 'not_started', '株式・新株予約権による対価の規定なし', '知的財産ポリシー（平成21年4月1日制定、令和2年3月4日改正）7項は「譲渡、実施許諾等により得た収入の一定割合を還元する」と定め、対価は金銭収入を前提とする。教職員の職務発明に関する規程（法人規程第31号）第11条は登録補償金、第12条は実施補償金を規定し、実施許諾による収入額の100分の50、譲渡による収入額の100分の50を発明者へ支払う建て付けで、株式・新株予約権の語は全10ページ中に一度も現れない。規則・規程一覧にも株式・新株予約権に関する規程は無い。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/23765.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'pol_fund_investment', 'not_started', '出資・ファンドの規程なし（定款の業務範囲外）', '京都府公立大学法人定款第24条（業務の範囲）は、大学の設置運営、学生への援助、受託・共同研究等の連携、生涯学習機会の提供、教育研究成果の普及及び活用、附帯業務の6号のみを掲げ、法人からの出資に関する号を含まない。第26条の出資は京都府から法人への資本金出資を指す。規則・規程一覧にも大学VC、認定VC、LP出資、指定ファンドに関する規程は無い。KSAC-GAPファンドはJST基金による研究開発費の助成で、株式取得を伴う投資ではない。', 'official', 'https://www.kpu-m.ac.jp/corporation/teikan.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_regulation_owner', 'unknown', null, '［自動検証で否認: 地方独立行政法人が正しく学校法人表記は誤り］元の主張(established): 学校法人規程（公立大学法人の規程、両大学共通）。認定規程は「京都府公立大学法人における大学発ベンチャー企業の認定等に関する規程」（令和7年1月31日、京都府公立大学法人規程第49号）で、大学単位ではなく設置法人単位の規程。第3条で府立医大に京都府立医科大学発ベンチャー審査委員会、府立大に京都府立大学発ベンチャー審査委員会をそれぞれ置き、1本の規程で2大学を運用する。設置者は地方独立行政法人法に基づく京都府公立大学法人であり、私立の学校法人ではない点は語彙選択上の読み替え。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_review_body', 'established', '京都府立医科大学発ベンチャー審査委員会', '認定規程第3条第1項で府立医大に設置。第2項は委員会に関し必要な事項を別に定めるとし、委員構成の内規は公開されていない。第4条の流れは、代表者が認定申請書（様式第1号）を理事長へ提出、理事長が当該審査委員会へ審査を付託、委員会が別に定める審査（認定）基準に基づき審査し審査結果を理事長へ上申、理事長が法人理事会で認定・不認定を審議、結果通知書（様式第2号）で通知。事務は第13条により法人は経営戦略室、府立医大は大学事務局研究支援課が所掌。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_equity_decider', 'not_started', '規定なし（株式・新株予約権の取得制度が無い）', '法人の規則・規程一覧に株式・新株予約権の取得や処分に関する規程は存在せず、定款第24条の業務の範囲にも出資が含まれないため、決裁者を定める必要が生じていない。認定規程の便宜措置（第7条）は施設・登記・設備の現物支援に限られ、対価として株式を受け取る条項も無い。知的財産ポリシーおよび職務発明規程の対価は金銭収入のみ。', 'official', 'https://www.kpu-m.ac.jp/corporation/kisoku.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_amendment_decider', 'established', '理事長（法人規程第49号として制定、事務は総務室）', '認定規程本文に改廃条項は無い。制定形式は京都府公立大学法人規程第49号（令和7年1月31日制定、令和7年4月1日施行）で、法人規程は理事長名で制定される。組織規則（法人規則第1号）第13条第4号が、法人本部総務室の所掌事務として「規則及び法人本部が所掌する規程の制定及び改廃に関すること」を掲げる。定款第17条の理事会議事事項は中期目標・知事の認可事項・予算決算・重要組織の設置廃止・その他理事会が定める重要事項の5号で、規程の制定改廃は列挙されていない。なお理事会規程（法人規程第1号）第7条は同規程自身の改廃に理事会の議を要すると定める。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/41436.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_post_grad_limit', 'not_started', '規定なし（学生は在籍中に限定、退職後の条項なし）', '認定規程第2条第5号は学生を「京都府立医科大学又は京都府立大学に在籍中の学部生、大学院生及び研究生」および「その他理事長が特に認めた者」と定義し、第4号の教職員は「本法人と雇用関係がある者」に限る。退職・卒業・修了後の何年以内という期限条項は全14条に存在しない。ただし第2条第1号アの知的財産活用型は「本法人に帰属する知的財産を活用するために設立の準備を行い、又は設立した企業」であり在籍要件を課さないため、退職者・修了者の企業でも法人帰属知財を使うなら申請の余地がある。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_renewal_rule', 'established', '更新可（審査あり）：再申請で延長', '認定規程第4条第6項ただし書「再申請による延長を妨げない」。届出のみの更新手続を定めた条文は無く、再申請は第4条第1項の認定申請書提出から審査委員会の審査、理事長への上申、法人理事会の審議という当初認定と同じ経路をたどる。第7条第2項も便宜措置の期間について、同じただし書を引いて再申請による延長を認める。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_naming', 'established', '大学発ベンチャー（称号「京都府立医科大学発ベンチャー」）', '認定規程第6条第1項で理事長が称号記（様式第4号）により大学発ベンチャーの称号を授与。第2項で府立医大に関連する認定ベンチャーは「京都府立医科大学発ベンチャー」、府立大に関連するものは「京都府立大学発ベンチャー」の称号を使用できる。第3項で当該大学のロゴマークの使用も認める。規程名・条文とも一貫して「大学発ベンチャー」表記で、「スタートアップ」の語は使われていない。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_support_period', 'established', '支援ごとに別に定める（認定期間内で学長が決定）', '認定規程第7条第2項「前項に規定する便宜措置を行う期間は、第4条第6項の規定により認定した期間の末日までにおいて称号付与大学の学長が定める」。称号とロゴマークの使用期間は第6条第4項で認定期間の末日までと固定されるのに対し、便宜措置の期間は認定期間の末日を上限として学長が個別に設定する二段構え。様式第7-1号の便宜措置通知書にも便宜措置期間の記入欄がある。再申請による延長は妨げられない。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_support_contents', 'established', '施設貸与・商業登記許可・研究設備利用・称号とロゴ使用・GAPファンド公募', '認定規程第7条第1項が事務室又は研究室としての施設貸与（第1号）、貸与施設を所在地とする商業登記の許可（第2号）、研究設備等の利用許可（第3号）、その他学長が必要と認めること（第4号）を列挙。第6条が称号とロゴマークの使用を認める。これに加え研究支援課がKSAC-GAPファンド（JST大学発新産業創出基金事業スタートアップ創出プログラム）を学内公募し、産学公連携機構K-MICSが無料の技術相談、共同研究、受託研究、知的財産、利益相反管理の窓口となる。資金の直接供与、人材紹介、広報支援は規程に無い。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_f77a046888fb', 'attr_source_docs', 'established', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf・https://www.kpu-m.ac.jp/corporation/kisoku.html・http…', '1本目が認定制度の正本（法人規程第49号、全14条＋様式第1号から第10号までを収録した12ページのPDF）。2本目は京都府公立大学法人の規則・規程一覧で、定款、業務方法書、知的財産ポリシー、職務発明規程、利益相反規程、兼業規程へのリンクを持ち、出資・株式規程が存在しないことの確認にも使える。3本目は産学公連携機構K-MICS（令和6年4月1日設置）の紹介ページで、支援メニューと相談窓口の所在を示す。', 'official', 'https://www.kpu-m.ac.jp/corporation/files/49bentyakitei1R70401.pdf', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_cert_update', 'established', '5年間・更新規定なし、再申請可', '認定規程第6条第2項「『信州大学発スタートアップ』の称号は，5年間使用することができる。ただし，再申請することを妨げないものとする。」更新の届出や更新審査を定めた条項はなく、期間満了後に継続する場合は第3条の認定申請書を再提出し、第5条第2項により認定委員会の議を経て学長が改めて認定する。要件の再確認手続きを独立して定めた条文は不見当。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_title_restriction', 'established', '称号は5年間使用可、取消後は認定の事実を活用禁止', '認定規程第6条第2項で使用期間を5年と限定。第10条第3項「速やかに称号記を返付するものとし，当該取消しを受けた日以降，大学発スタートアップとして認定を受けていた事実を事業において活用してはならない」。第7条は「第5条第2項の認定及び第6条第1項の称号の授与は，本法人に何ら法的責任を生じさせるものではない」と免責を置くのみで、品質保証・投資推奨・経営状態の保証と誤認させない旨の明文条項は不見当。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_cancellation', 'established', '取消3事由・称号記返付・取消後の営業利用禁止', '認定規程第9条は代表者からの認定解除申請書（別記様式第3号）による解除と称号の返付を定め、学長はこれを認めるものとする。第10条第1項は取消事由として社会的信用を失墜する行為、第8条第1項の事業報告書等の未提出または同条第2項の報告があった場合、その他不名誉となるおそれがある場合の3号を列挙し、認定委員会の議を経て学長が取り消す。第2項で別記様式第4号による通知、第3項で称号記の返付と取消し後の利用禁止を規定。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_report_change', 'established', '年次の事業報告書・収支決算書と解散等の報告義務', '認定規程第8条第1項は代表者に対し、年度毎に適宜の様式により自社で定めた決算日から3か月以内に事業報告書及び収支決算書を学長へ提出する義務を課す。第2項は会社法上の解散、破産手続開始決定、民事再生手続開始決定、会社更生手続開始決定、不正競争防止法違反の有罪確定の5事由について速やかな報告を求める。代表者・所在地・資本構成の変更届を定めた条文は規程本文に不見当。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_support_request', 'established', '支援ごとに関係規則等で個別手続、専用細則なし', '認定規程第11条第2項「前項の各号に規定する支援を行うときは，本法人における関係規則等によるものとする」。施設についてはオープンベンチャー・イノベーションセンター規程第7条が「施設の貸付に関し必要な事項は，国立大学法人信州大学不動産貸付事務細則によるほか，センター長が別に定める」と再委任している。認定規程の別記様式は認定申請書・称号記・認定解除申請書・認定取消通知の4種のみで、支援申請専用の様式や支援細則は規程集の目次に不見当。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_facility_registration', 'established', '5キャンパスの施設貸与、学内住所で商業登記可', '認定規程第11条第1項第1号でインキュベーション施設等の貸与、第2号で「貸与したインキュベーション施設等について，大学発スタートアップの所在地とする商業登記を認めること」を定める。起業ガイド05は認定企業への支援として施設貸与と学内住所での商業登記の許可を挙げ、松本・長野（工学）・長野（教育）・上田・伊那の各キャンパスのシェアオフィスとOVIC、Fii、AREC等を列挙。シェアオフィスは起業時の会社登記と起業済企業の移転登記が可能と明記。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_vc_connection', 'established', 'VC・地域金融機関とのマッチング、連携支援機関7機関', '産学官連携推進機構のスタートアップ支援ページはハンズオン支援として「ベンチャーキャピタル・地域金融機関とのマッチング」を掲げ、連携支援機関にNES、KDDI、NEDO、信州TLO、長野県・信州スタートアップステーション、三井住友信託銀行、レジェンド・パートナーズを列挙。起業ガイド05は認定企業への支援に金融機関や事業会社とのマッチングを含め、IJIEは自治体・地域金融機関と連携する地域プラットフォームと説明。認定規程第11条第1項第4号も紹介・仲介を規定。', 'official', 'https://www.shinshu-u.ac.jp/institution/suirlo/irl/startup.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_eir', 'not_started', '客員起業家の招聘制度なし', '規程集の目次を「起業家」「客員」で確認したところ客員教授等選考基準があるのみで、客員起業家やEIRに相当する規程は存在しない。認定規程第11条第1項の支援は施設貸与、商業登記、相談業務、紹介・仲介、広報、その他学長が必要と認めることの6号列挙で、起業家人材の招聘は含まれない。スタートアップ支援ページと起業ガイドの支援メニュー10項目にも記載がない。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/aggregate/catalog/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_cxo_pool', 'unknown', null, '［自動検証で否認: ガイド14頁にCxO候補人材マッチングの記載あり］元の主張(not_started): 経営人材の紹介・マッチング制度なし。起業ガイド02はCEO・CTOに加えCFO・COOを採用してチームを作ることが成功のカギと解説するが、大学が候補人材を紹介・マッチングする制度は記載していない。支援メニュー10項目（IJIE、ハンズオン支援、大学発技術系ベンチャー実践論、ベンチャーピッチ、認定、POCファンド、株式等によるライセンス対価、外部機関連携、シェアオフィス、インキュベーション施設）にも人材プールはない。認定規程第11条第1項第4号の紹介・仲介は他企業への紹介であり経営人材の斡旋ではない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_ip_equity', 'established', 'ライセンス対価を株式・新株予約権で取得する規程あり', '国立大学法人信州大学における認定大学発スタートアップを対象としたライセンス等の対価として取得する株式等取扱規程。第3条は事業の有望性が高いこと、現金による支払いの免除または軽減が特に必要と認められること、反社会的勢力などとの関係がないことを要件とする。第4条で審査委員会が審査し委員長（学術研究・産学官連携推進機構長）が学長へ報告、第5条で学長が取得の可否を決定、第6条で財務部が管理、第7条で予算決算及び出納事務取扱規程第59条第2項に基づき評価。対象は認定スタートアップに限定。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001254.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'pol_fund_investment', 'not_started', '大学の出資・ファンド組成規程なし', '規程集の目次を「出資」「投資」「ファンド」「新株予約権」で確認したところ該当規程なし。株式関係は寄附により取得する株式取扱規程と認定大学発スタートアップのライセンス対価株式等取扱規程の2件のみで、いずれも大学からの出資ではない。信州大学POCファンドとIJIE-GAPファンドプログラムは起業前シーズへ研究開発費を支給する制度であり、起業ガイドでもベンチャーキャピタルは外部の資金調達先として説明されている。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/aggregate/catalog/index.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_regulation_owner', 'established', '大学規程（信州大学規程第158号）', '国立大学法人信州大学における大学発スタートアップの認定に関する規程（平成30年国立大学法人信州大学規程第158号）。国立大学法人の学内規程として制定され、附則により令和元年度規程第92号、令和3年度規程第29号、令和4年度規程第141号、令和5年度規程第112号で改正、現行版は令和6年4月1日施行。下位に学術研究・産学官連携推進機構の認定委員会細則を置く二層構成。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_review_body', 'established', '信州大学学術研究・産学官連携推進機構大学発スタートアップ認定委員会', '認定規程第4条で認定委員会を置き、第5条第2項で学長は認定委員会の議を経て認定を決定。委員会細則第2条の審議事項は認定、認定及び称号授与の取消し、その他必要な事項。第3条の委員は機構長、学術研究支援本部長、新価値創成本部長、リサーチアドミニストレーション室長、スタートアップ・事業化推進室長、知的財産室長、研究推進部長、総務部長、人事課長、広報室長ほか。第4条で委員長は機構長、第5条で3分の2以上の出席と出席委員の過半数で議決。庶務は研究推進部。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001086.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_equity_decider', 'established', '学長（審査委員会の審査結果に基づき決定）', '株式等取扱規程第4条で審査委員会が取得の可否を審査し、委員長である学術研究・産学官連携推進機構長が学長に報告。第5条「学長は，前条第6項の規定により報告された審査結果に基づき，株式等の取得の可否について決定する」。第10条第4項は新株予約権の取扱いについて学長の承認を得た上で対応すると定める。第9条の売却は本法人が速やかに売却するものとするのみで決裁者の明示はない。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001254.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_amendment_decider', 'established', '学長（規則等制定基準が定める規程の制定権者）', '国立大学法人信州大学規則等制定基準第4条第1項は、規程について制定権者を学長または部局の長、審議機関を必要に応じて経営協議会、教育研究評議会その他関係委員会と定める（規則は学長が経営協議会または教育研究評議会の審議を経て制定）。第4条第2項に審議機関への付議を省略できる4類型がある。認定規程の附則はいずれも学長名の規程番号で改正されており、直近は令和6年3月18日令和5年度規程第112号。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110000065.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_post_grad_limit', 'established', '3年以内', '認定規程第2条第3号は、教職員・学生等が発起人または設立時に取締役相当となって起業したものについて「教職員、学生等が退職、卒業等の後に起業した場合については、退職、卒業等から起業までの期間が3年以内のものに限る」と定める。起業ガイド05の定義欄にも同一の記載がある。他の類型（帰属知的財産権ベース、研究成果・技術ベース、学長が特に必要と認めるもの）には期限の定めがない。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_renewal_rule', 'established', '更新不可・再申請（5年経過後に認定手続をやり直し）', '認定規程第6条第2項「『信州大学発スタートアップ』の称号は，5年間使用することができる。ただし，再申請することを妨げないものとする。」更新の届出や更新審査を定めた条項はなく、継続を望む場合は第3条の認定申請書（別記様式第1号）を再提出し、第5条第2項により認定委員会の議を経て学長が改めて認定する形になる。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_naming', 'established', '大学発スタートアップ（称号は「信州大学発スタートアップ」）', '認定規程第6条第1項「学長は，前条第2項により認定した大学発スタートアップに対し，称号記（別記様式第2号）により，『信州大学発スタートアップ』の称号を授与するものとする」。規程名も大学発スタートアップの認定に関する規程で、ベンチャーの語は用いていない。ただし産学官連携推進機構の旧掲載資料には信州大学発ベンチャー認定企業の表記が残る。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_support_period', 'established', '支援ごとに別に定める（関係規則等による）', '認定規程第11条第1項は認定大学発スタートアップに対し本法人の管理運営及び教育研究に支障のない範囲で支援を行うことができると定めるのみで、支援期間の定めはない。第2項「前項の各号に規定する支援を行うときは，本法人における関係規則等によるものとする」。施設貸付はオープンベンチャー・イノベーションセンター規程第7条により不動産貸付事務細則等へ委ねられる。称号の使用期間5年（第6条第2項）とは別立ての構造。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_support_contents', 'unknown', null, '［自動検証で否認: 第11条は6号のみ、POC/株式/教育は同条外］元の主張(established): 施設貸与・商業登記・相談・紹介仲介・広報・POCファンド・株式対価・起業家教育。認定規程第11条第1項の支援は、インキュベーション施設等の貸与、貸与施設での商業登記の承認、教職員等による起業・経営相談、他企業への紹介・仲介、イベントや広報誌・ホームページでの広報、その他学長が必要と認めることの6号。起業ガイドの支援メニューはIJIE、ハンズオン支援、大学発技術系ベンチャー実践論、信州大学ベンチャーピッチ、認定制度、POCファンド、株式・新株予約権によるライセンス対価、外部機関との連携、シェアオフィス、インキュベーション施設の10項目。共用機器の優遇利用は記載がない。', 'unknown', null, '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_355ac37a0d09', 'attr_source_docs', 'established', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html・https://www.shinshu-u.ac.jp/guidance/regulations/ac…', '1本目は認定規程本体（別記様式一覧を含む）、2本目は認定大学発スタートアップを対象としたライセンス等の対価として取得する株式等取扱規程、3本目は学術研究・産学官連携推進機構のスタートアップ支援ページ。補助として認定委員会細則（110001086）、規則等制定基準（110000065）、起業ガイドPDF（SUGuidebook_2024_Web.pdf）を参照した。', 'official', 'https://www.shinshu-u.ac.jp/guidance/regulations/act/110001085.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_cert_update', 'not_started', '有効期間・更新の定めなし（令和2年改正で廃止）', '称号授与規程第9条は「称号の授与は、別に定める称号記の交付をもって行う」のみで、有効期間も更新審査も置いていない。附則（令和2年4月1日海大達第49号）第3項が、旧規程で称号を授与された企業の「称号授与の期間及びその更新については、改正後の第9条の規定にかかわらず、なお従前の例による」としており、令和2年改正で期間と更新の仕組みを廃止したことが読める。要件の再確認は、更新審査ではなく第11条の年次報告と第12条第1項第1号の取消事由で担保する構成。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_title_restriction', 'established', '大学の免責条項と、取消後の称号使用禁止', '第10条（大学の免責）は「本学は、称号の授与により、称号を授与された企業又は第三者に損害が生じた場合には、これによって生じた損害を賠償する義務を負わない」と規定。第12条第2項は取消しを受けた企業が「当該取消しを受けた日以後、称号の授与を受けていた事実を事業に使用してはならない」として使用停止を定める。ただし品質保証・投資推奨・経営状態の保証と誤認させない旨の明文や、称号の使用範囲を限定する条項は置いていない。認定ロゴ（縦型・横型）は大学が配布する運用。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_cancellation', 'established', '取消事由10号・取消後の使用禁止・取消の公表', '第12条第1項は、総長が委員会の議を経て称号を取り消せる事由を10号列挙する。対象企業要件（第3条第1項第1号・第2号・第5号・第6号）に該当しなくなったとき、本学又は当該企業の社会的信用を失墜する行為、活動内容報告の懈怠、辞退の文書申出、会社法上の解散、破産・民事再生・会社更生の各手続開始決定、不正競争防止法違反の有罪確定、その他保持させることが適当でないと総長が認めたとき。第2項で取消後の営業利用を禁止し、第13条で取消しをウェブサイト等により公表する。称号記の返付を求める規定は置いていない。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_report_change', 'established', '毎年6月末までに活動内容報告書、変更届の定めなし', '第11条（活動内容等の報告）は「称号を授与された企業は、毎年6月末日までに、別に定める活動内容報告書により、総長に活動内容を報告しなければならない」と規定し、第12条第1項第3号で報告の懈怠を取消事由とする。一方、代表者・所在地・資本構成の変更届に関する規定はない。解散は第12条第1項第5号で取消事由として扱う構成で、解散時の報告義務としては定めていない。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_support_request', 'established', 'HX法人会員・GAPファンドなど支援ごとに個別申請', '称号認定は「北大発認定スタートアップ企業の称号付与について」の申請書（Word様式）に履歴事項全部証明書・定款の写し・株主名簿等を添えて提出し、面談と審査を経る手続。これとは別に、HXの利用は「様式1号（法人会員登録申請書兼法人会員有料サービス利用申請書）」に事業概要説明資料・履歴事項全部証明書・代表者の職務経歴書・株主名簿等を添えて申請し、利用開始まで最大2か月程度を要すると案内。レンタルラボは北大リサーチ＆ビジネスパークの管理法人ごとに入居申込、GAPファンドはHSFCの年度公募採択と、支援ごとに申請と審査を分けている。', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/hx/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_facility_registration', 'established', 'HX有料法人会員で本店登記可、周辺にレンタルラボ', '「広域エリア統合プレインキュベーション拠点HX〈エイチクロス〉」ページの会員制度で、無料法人会員はコワーキング・コミュニティスペース利用等、有料法人会員は「HXの本店所在地としての住所登記」「FMI国際拠点の所定郵便受けの利用」「同会議室の利用」を追加。有料会員の対象は、本学の研究成果を活用した事業を営み、申請時に法人設立後2年以内、株式会社、未上場かつ将来的に上場を目指す企業で、設立予定の企業も事前申込可。実験系の場所は「レンタルラボ」ページのとおり北大リサーチ＆ビジネスパーク（北キャンパスエリア）に集積し、管理法人ごとに入居申込を行う。', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/hx/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_vc_connection', 'established', 'HSFCに金融機関・VCが協力機関として参画', '北海道大学を主幹機関とする「北海道未来創造スタートアップ育成相互支援ネットワーク（HSFC）」の参画機関ページに「金融機関・VC」の区分があり、北洋銀行、北海道銀行、北海道ベンチャーキャピタル、15th Rock、D2 Garage、日本政策金融公庫、日本政策投資銀行、みずほ銀行、三井住友銀行、三井住友信託銀行、三菱UFJ銀行、三菱UFJ信託銀行、ゆうちょ銀行、あずさ監査法人、帯広信用金庫が掲載されている。同ページは「GAPファンドへのエントリーが可能な共同機関への参画だけでなく、金融機関の協力機関化も進めています」と記載。自治体（北海道、札幌市、旭川市ほか）も協力機関に含む。', 'official', 'https://hsfc.jp/about', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_eir', 'established', '客員起業家（EIR）の規程整備済み', 'HSFC「起業支援」ページの「経営者候補の人材戦略」節に、見出し「客員起業家（EIR）制度」として「HSFCでは、主幹機関である北海道大学において、客員起業家（EIR）の規程整備を完了しております」と明記されている。ただし規程の正式名称・本文は北海道大学の規程データベース（Reiki-Base）の公開分では確認できず、任用条件・処遇・任期は未確認。', 'official', 'https://hsfc.jp/insights/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_cxo_pool', 'established', '外部CXOマッチングと首都圏UIJターン人材の接続', 'HSFC「起業支援」ページの「経営者候補の人材戦略」節に「CXO人材マッチング」の見出しがあり、「HSFCでは外部CXOマッチング施策を活用し、研究者ー経営候補者の接続を進めています」と記載。道内出身者や北海道への移住意向層のUIJターン候補を中心に首都圏でマッチングイベントを実施し、札幌市と連携して首都圏拠点を利活用しながらマッチング後の伴走支援も行うとする。事例として札幌市連携「北海道BRAVE2024」（Beyond Next Ventures運営の事業化推進プログラム、約3か月）と、NEDO「大学発スタートアップにおける経営人材確保支援事業（MPM）」に北海道共創パートナーズが採択された取組を掲載。', 'official', 'https://hsfc.jp/insights/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_ip_equity', 'established', 'ライセンス対価として株式・新株予約権を取得可', '「国立大学法人北海道大学におけるライセンス等又はスタートアップ支援の対価として取得する株式等の取扱いに関する規程」（令和2年海大達第50号、令和6年1月1日改正施行）第1条で株式及び新株予約権を「株式等」と定義。第2条で、知的財産の譲渡若しくは提供、実施権の設定又は実施権若しくは利用権の許諾（ライセンス等）と、北大発認定スタートアップ企業への研究開発成果の普及・活用促進に必要な支援を対価取得の対象とする。第4条第1項で、ライセンス等の対価としての取得は知的財産専門部会の審査を経て産学・地域協働推進機構長が可否を決定。第5条第1項は取得後速やかに売却するものとし、特別の事情がある場合に保有を認める。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000929.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'pol_fund_investment', 'established', '15th Rockと協定した北大Green Frontier Fund', 'ベンチャーキャピタル15th Rockの公表資料によれば、北海道大学と15th Rockが協定を締結し、大学発ファンド「北大Green Frontier Fund投資事業有限責任組合」を2024年春に設立、目標総額を掲げ存続期間10年で組成。投資対象は第一次産業・GX等の「Green」領域と、北海道大学関連（出身者、研究成果など）の「Frontier」領域。出資者は国内の金融機関・事業会社が中心とされ、大学自身が出資者として明記されているわけではない。大学が直接出資するための規程はReiki-Baseの公開分では確認できず未確認。なお称号授与規程第3条第1項第7号は「出資、施設の貸与その他の本学からの支援を受けて設立した企業」を対象類型に含む。', 'official', 'https://15th-rock.com/%E5%8C%97%E6%B5%B7%E9%81%93%E5%A4%A7%E5%AD%A6%E3%81%A815th-rock%E3%81%8C%E5%A4%A7%E5%AD%A6%E7%99%BA%E3%83%95%E3%82%A1%E3%83%B3%E3%83%89%E3%80%8C%E5%8C%97%E5%A4%A7green-frontier-fund%E3%80%8D%E3%82%92/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_regulation_owner', 'established', '大学規程（海大達第262号の学内規程）', '規程名は「国立大学法人北海道大学における北大発認定スタートアップ企業称号授与規程」。国立大学法人北海道大学の学内規程（海大達）として平成27年11月1日海大達第262号で制定され、平成31年・令和2年・令和3年・令和4年・令和5年・令和6年に改正、令和6年1月1日海大達第5号が最終改正・施行。学校法人規程や産学・地域協働推進機構の独自規程ではなく、大学本体の規程として称号制度を定めている。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_review_body', 'established', '北大発認定スタートアップ企業審査委員会', '第4条第1項で「北大発認定スタートアップ企業審査委員会」を置き、称号の授与と、株式等取扱規程第4条第2項のスタートアップ支援の対価としての株式等取得の可否を審査すると規定。第2項の委員は、総長が指名する産学・地域協働推進機構副機構長1名、同機構スタートアップ創出本部長、同副本部長、同本部の部門長、社会共創部産学連携課長。第5条で委員長は副機構長の委員が充たる。第6条は委員の3分の2以上の出席と出席委員の過半数による議決。第8条で総長が申請を委員会に付託し、委員会が審査結果を総長に報告する。事務は第14条により社会共創部産学連携課が処理。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_equity_decider', 'established', '産学・地域協働推進機構長（専門部会等の審査を経る）', '株式等取扱規程第4条第1項で、ライセンス等の対価として取得する株式等は知的財産専門部会の審査を経て産学・地域協働推進機構長が取得の可否を決定。第4条第2項で、スタートアップ支援の対価としての株式等は北大発認定スタートアップ企業審査委員会の審査を経る（称号授与規程第4条第1項と対応）。処分については第5条第1項が取得後速やかに売却するものとし、特別の事情がある場合に限り保有を認める。管理担当は産学・地域協働推進機構。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000929.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_amendment_decider', 'established', '総長（海大達として制定改正、改廃条項なし）', '称号授与規程には改廃決裁者を定める条項がなく、第15条（雑則）が「この規程に定めるもののほか、称号の授与に関し必要な事項は、総長が別に定める」と規定するにとどまる。規程自体は平成27年11月1日海大達第262号として制定され、令和6年1月1日海大達第5号まで6回改正されている学内規程（海大達）。役員会規程（平成16年海大達第62号）第2条の審議事項は中期目標の意見、文部科学大臣の認可・承認事項、予算・決算、研究科・学部その他の重要な組織の設置廃止、その他役員会が定める重要事項であり、学内規程の制定改廃は列挙されていない。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_post_grad_limit', 'established', '1年以内', '第3条第1項第6号は、本学を退職した教職員又は卒業・修了した学生（退職教職員等）が「当該退職又は卒業若しくは修了の日から起算して1年を経過する日までの間に」発起人となり、又は取締役その他これに準ずる者として設立した企業であって、当該退職教職員等が現に在籍しているものを対象とする。ただし「退職教職員等が当該設立の日までに他の職に就いていない場合に限る」との限定付き。なお第3号・第4号は、企業の設立から5年以内に本学と共同研究を実施した、又は本学から技術移転・成果有体物の提供を受けた企業を別類型として拾う。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_renewal_rule', 'established', '期限なし（令和2年改正で期間と更新を廃止）', '現行第9条は称号記の交付だけを定め、称号授与の期間も更新手続も置いていない。附則（令和2年4月1日海大達第49号）第3項が、改正前の「北大発ベンチャー称号授与規程」により称号を授与されている企業の「称号授与の期間及びその更新については、改正後の第9条の規定にかかわらず、なお従前の例による」と経過措置を置いていることから、令和2年改正で期間と更新を廃止し、以後の認定は期限なしとなったと読める。維持管理は第11条の年次報告と第12条の取消しで行う。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_naming', 'established', '独自名称：北大発認定スタートアップ企業', '第2条「本学がこの規程に基づき企業に授与する称号（以下単に「称号」という。）は、北大発認定スタートアップ企業とする」。附則（令和3年8月1日海大達第115号）第2項で、改正前の規程により「北大発ベンチャー」の称号を授与されている企業は、施行日に改正後の規程による「北大発認定スタートアップ企業」の称号を授与されたものとみなすとされ、令和3年8月に呼称を変更している。産学・地域協働推進機構のページも同じ呼称を用い、認定ロゴを縦型・横型で配布。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_support_period', 'established', '支援ごとに別に定める（称号自体は期限なし）', '称号授与規程には支援の内容も支援期間も規定がなく、第9条は称号記の交付のみを定める。称号そのものは期限がない一方、個別の支援は制度ごとに期間が決まる構成で、HXの法人会員は年額の有料サービスとして年単位、GAPファンドはHSFCの年度公募で採択期間が定まり、レンタルラボは北大リサーチ＆ビジネスパークの各運営法人との賃貸契約による。HXの有料法人会員はさらに「申請時に法人設立後2年以内」という利用資格の期間制限を持つ。', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/hx/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_support_contents', 'established', '起業相談窓口・称号記と認定ロゴ・HXコワーキング・本店所在地登記・会議室と郵便受け・レンタルラボ紹介・GAPファンド・起業塾とピッチとアクセラレータープログラム・アントレプレナーシップ教育・客員起業家（EIR）・CXO人材マッチング・金融…', '「起業支援」ページに起業相談窓口（学内者・学外者別フォーム）と「研究者向け起業ガイド」。「称号付与について」ページに称号記と認定ロゴの送付。HXページにコワーキング・コミュニティスペース利用、有料法人会員による本店所在地登記・郵便受け・会議室利用、Xディレクターによるコンサルティング、起業塾・スクール・ピッチイベント、アクセラレータープログラム。HSFC「起業支援」ページにGAPファンド、客員起業家（EIR）制度、CXO人材マッチング。「参画機関」ページに金融機関・VC。「レンタルラボ」ページに北大リサーチ＆ビジネスパークの施設案内。機構の事業案内に共同研究・受託研究・学術コンサルティング。', 'official', 'https://www.mcip.hokudai.ac.jp/business/venture/hx/', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910'),
  ('inst_catalog_7c5298d724e8', 'attr_source_docs', 'established', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html ・ https://www.mcip.hokudai.ac.jp/business/ventur…', '1本目は称号制度の正本である「国立大学法人北海道大学における北大発認定スタートアップ企業称号授与規程」の現行本文（令和6年1月1日施行、規程データベースReiki-Base）。2本目は産学・地域協働推進機構の称号付与ページで、8つの申請要件、提出書類、面談と審査の流れ、認定ロゴを掲載。3本目はHSFCの起業支援ページで、GAPファンド、重点3領域、客員起業家（EIR）制度、CXO人材マッチングを掲載。株式等の取扱いは規程本文 https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000929.html 、施設と登記はHXページが補完資料となる。', 'official', 'https://www.hokudai.ac.jp/jimuk/reiki/reiki_honbun/u010RG00000824.html', '2026-09-10', 'えいみ-ultracode-調査20260905-照合20260910')
